# 第 10 批（F3）：海岸管理法（104/02/04）第 1 條至第 46 條（全部條文）
# ※ 四個選項刻意寫成相近長度。
CM = "ENV-15"
Q = [
# ---------- 第一章 總則 ----------
(CM,"第1條",1,"海管法-立法目的",
 "制定海岸管理法之立法目的為何？",
 ["為維繫自然系統、確保自然海岸零損失、因應氣候變遷、防治海岸災害與環境破壞、保護與復育海岸資源、推動海岸整合管理，並促進海岸地區之永續發展","為加速海埔新生地開發、確保填海造地零障礙、因應產業需求、促進臨海工業發展、擴大海岸土地供給、推動海岸開發整合，並提升海岸地區之投資效益","為統一海域執法權責、確保海岸巡防零死角、因應偷渡走私、防杜海岸治安事件、保護海岸軍事設施、推動海岸監控管理，並強化海岸地區之國防安全","為健全漁港與商港建設、確保航道水深零淤積、因應航運成長、防治船舶污染海域、保育近海漁業資源、推動港灣整合管理，並促進海運產業之永續經營"],"a",
 "第1條：為維繫自然系統、確保自然海岸零損失、因應氣候變遷、防治海岸災害與環境破壞、保護與復育海岸資源、推動海岸整合管理，並促進海岸地區之永續發展，特制定本法。第7條進一步揭示海岸地區之規劃管理原則，以優先保護自然海岸並維繫海岸之自然動態平衡為首要。",
 "What is the stated legislative purpose of the Coastal Zone Management Act?",
 ["To sustain natural systems, ensure zero loss of natural coastline, adapt to climate change, prevent coastal hazards and environmental damage, protect and restore coastal resources, promote integrated coastal management and sustainable coastal development","To accelerate reclaimed land development, ensure zero obstacles to land reclamation, meet industrial demand, promote coastal industry, expand the supply of coastal land, promote integrated coastal development and raise coastal investment returns","To unify maritime enforcement powers, ensure coast guard patrols leave no gaps, address smuggling and illegal entry, prevent coastal security incidents, protect coastal military installations and strengthen national defense along the coast","To improve fishing and commercial port works, ensure zero silting of navigation channels, meet shipping growth, prevent vessel pollution, conserve inshore fishery resources, promote integrated harbor management and sustainable shipping operations"],
 "Article 1; Article 7."),

(CM,"第2條",3,"海管法-海岸地區定義",
 "本法所稱海岸地區中，濱海陸地與近岸海域之劃定原則為何？",
 ["濱海陸地以平均高潮線至第一條省道、濱海道路或山脊線之陸域為界；近岸海域以平均高潮線往海洋延伸至三十公尺等深線，或平均高潮線向海三浬涵蓋之海域，取其距離較長者為界，並不超過領海範圍","濱海陸地以平均低潮線至第一條縣道或防潮堤之陸域為界；近岸海域以平均低潮線往海洋延伸至五十公尺等深線，或平均低潮線向海十二浬涵蓋之海域，取其距離較短者為界，並得超過領海範圍","濱海陸地以海堤堤址向陸側延伸一千公尺之陸域為界；近岸海域以海堤堤址往海洋延伸至二十公尺等深線，或向海一浬涵蓋之海域，取其距離較長者為界，並不超過鄰接區範圍","濱海陸地以平均高潮線至最近都市計畫區界之陸域為界；近岸海域以平均高潮線往海洋延伸至一百公尺等深線，或向海六浬涵蓋之海域，取其距離較短者為界，並不超過專屬經濟海域"],"a",
 "第2條第1款：海岸地區指中央主管機關依環境特性、生態完整性及管理需要劃定公告之陸地、水體、海床及底土。濱海陸地以平均高潮線至第一條省道、濱海道路或山脊線之陸域為界；近岸海域以平均高潮線往海洋延伸至三十公尺等深線，或平均高潮線向海三浬涵蓋之海域，取其距離較長者為界，並不超過領海範圍之海域與其海床及底土；離島濱海陸地及近岸海域於不超過領海範圍內得視環境特性及實際管理需要劃定。第5條並要求中央主管機關於本法施行後六個月內劃定公告海岸地區範圍。",
 "How are coastal land and nearshore waters delimited within the coastal zone?",
 ["Coastal land runs from the mean high water line to the first provincial highway, coastal road or ridge line; nearshore waters run from the mean high water line to the 30-meter isobath or three nautical miles seaward, whichever is farther, not beyond the territorial sea","Coastal land runs from the mean low water line to the first county road or coastal seawall; nearshore waters run from the mean low water line to the 50-meter isobath or twelve nautical miles seaward, whichever is nearer, and may extend beyond the territorial sea limit","Coastal land runs 1,000 meters landward from the seawall foundation; nearshore waters run from the seawall foundation to the 20-meter isobath or one nautical mile seaward, whichever is farther, and not beyond the contiguous zone","Coastal land runs from the mean high water line to the nearest urban planning district boundary; nearshore waters run to the 100-meter isobath or six nautical miles seaward, whichever is nearer, and not beyond the exclusive economic zone"],
 "Article 2, subparagraph 1; Article 5."),

(CM,"第2條",2,"海管法-用詞定義",
 "本法所稱海岸災害及海岸防護設施，其定義為何？",
 ["海岸災害指在海岸地區因地震、海嘯、暴潮、波浪、海平面上升、地盤變動或其他自然及人為因素所造成之災害；海岸防護設施指堤防、突堤、離岸堤、護岸、胸牆、滯洪池、地下水補注設施、抽水設施、防潮閘門與其他防止海水侵入及海岸侵蝕之設施","海岸災害僅指在海岸地區因地震及海嘯所造成之重大災害，不含暴潮、波浪與地盤變動等因素；海岸防護設施僅指堤防、護岸及防潮閘門三類水利構造物，其餘突堤、離岸堤、胸牆、滯（蓄）洪池、地下水補注設施及抽水設施均不屬之","海岸災害指在海岸地區因船舶擱淺、油污外洩或廢棄物堆置所造成之環境災害；海岸防護設施指海岸巡防機關所設置之瞭望塔、監視系統、雷達站及其他防止非法入侵之設施，並包括防潮閘門與抽水設施在內","海岸災害指在近岸海域因漁業活動、海洋工程或觀光遊憩所引發之生態災害；海岸防護設施指人工魚礁、消波塊、養灘工程、紅樹林造林區及其他以生態工法設置之緩衝設施，不含堤防與防潮閘門等硬式構造"],"a",
 "第2條第2、3款：海岸災害指在海岸地區因地震、海嘯、暴潮、波浪、海平面上升、地盤變動或其他自然及人為因素所造成之災害；海岸防護設施指堤防、突堤、離岸堤、護岸、胸牆、滯（蓄）洪池、地下水補注設施、抽水設施、防潮閘門與其他防止海水侵入及海岸侵蝕之設施。第14條並就海岸侵蝕、洪氾溢淹、暴潮溢淹、地層下陷及其他潛在災害地區之劃設定有規定。",
 "How are coastal hazards and coastal protection facilities defined?",
 ["Coastal hazards are disasters in the coastal zone caused by earthquakes, tsunamis, storm surge, waves, sea level rise, ground movement or other natural and human factors; protection facilities include dikes, groins, detached breakwaters, revetments, parapets, detention ponds, groundwater recharge and pumping facilities, tide gates and other works","Coastal hazards mean only major disasters in the coastal zone caused by earthquakes and tsunamis, excluding storm surge, waves and ground movement; protection facilities mean only dikes, revetments and tide gates, with groins, detached breakwaters, parapets, detention ponds and pumping facilities excluded","Coastal hazards mean environmental disasters caused by ship groundings, oil spills or waste dumping in the coastal zone; protection facilities mean watchtowers, surveillance systems, radar stations and other anti-intrusion installations of the coast guard, together with tide gates and pumping facilities","Coastal hazards mean ecological damage in nearshore waters caused by fishing activities, marine engineering or tourism development; protection facilities mean artificial reefs, wave-dissipating blocks, beach nourishment works, mangrove planting areas and other eco-engineering buffer works, excluding hard structures such as dikes, revetments and tide gates"],
 "Article 2, subparagraphs 2 and 3; Article 14."),

(CM,"第3條",1,"海管法-主管機關",
 "本法所稱主管機關為何？",
 ["在中央為內政部；在直轄市為直轄市政府；在縣（市）為縣（市）政府","在中央為海洋委員會；在直轄市為直轄市政府；在縣（市）為縣（市）政府","在中央為經濟部；在直轄市為直轄市政府；在縣（市）為縣（市）政府","在中央為交通部；在直轄市為直轄市政府；在縣（市）為縣（市）政府"],"a",
 "第3條：本法所稱主管機關，在中央為內政部；在直轄市為直轄市政府；在縣（市）為縣（市）政府。第4條並定明近岸海域違法行為之取締、蒐證、移送等事項由海岸巡防機關辦理，主管機關仍應運用必要設施或措施主動辦理。",
 "Who are the competent authorities under this Act?",
 ["Central: the Ministry of the Interior; municipal: the municipal governments; county: the county or city governments","Central: the Ocean Affairs Council; municipal: the municipal governments; county: the county or city governments","Central: the Ministry of Economic Affairs; municipal: the municipal governments; county: the county or city governments","Central: the Ministry of Transportation; municipal: the municipal governments; county: the county or city governments"],
 "Article 3; Article 4."),

(CM,"第4條",2,"海管法-取締執行",
 "近岸海域違法行為之取締、蒐證、移送等事項由誰辦理？主管機關得要求哪些機關協助？",
 ["由海岸巡防機關辦理，主管機關仍應運用必要設施或措施主動辦理；並得要求軍事、海關、港務、水利、環境保護、生態保育、漁業養護或其他目的事業主管機關協助辦理","由主管機關自行辦理，海岸巡防機關僅於受請求時提供船艇支援；並得要求軍事、海關、港務、水利、環境保護、生態保育或其他目的事業主管機關代為執行全部取締事項","由各目的事業主管機關分別辦理，主管機關及海岸巡防機關均不直接介入；並得要求軍事、海關、港務、水利機關就其主管業務範圍內之違法行為逕行裁處並移送法辦","由警察機關會同海岸巡防機關辦理，主管機關僅負彙整統計之責；並得要求軍事、海關、港務、水利、環境保護或生態保育機關提供必要之場地、人力及經費支援"],"a",
 "第4條第1項：依本法所定有關近岸海域違法行為之取締、蒐證、移送等事項，由海岸巡防機關辦理；主管機關仍應運用必要設施或措施主動辦理。第2項：主管機關及海岸巡防機關就前項及本法所定事項，得要求軍事、海關、港務、水利、環境保護、生態保育、漁業養護或其他目的事業主管機關協助辦理。",
 "Who handles interception, evidence-gathering and referral for nearshore violations, and who may be asked to assist?",
 ["The coast guard handles them, while the competent authority must still act on its own initiative with necessary facilities or measures; military, customs, port, water, environmental, conservation, fishery and other industry authorities may be asked to assist","The competent authority handles them itself, with the coast guard only lending vessels on request; military, customs, port, water, environmental, conservation and other industry authorities may be asked to carry out all interception work instead","Each relevant industry authority handles them separately, with neither the competent authority nor the coast guard becoming directly involved; military, customs, port and water authorities may impose penalties and refer cases within their own remit","The police together with the coast guard handle them, with the competent authority only compiling statistics; military, customs, port, water, environmental or conservation authorities may be asked to supply premises, manpower and funding support"],
 "Article 4, paragraphs 1 and 2."),

(CM,"第5條",2,"海管法-範圍劃定",
 "中央主管機關應於何時劃定公告海岸地區範圍？公開展覽期間有何要求？",
 ["應會商地方主管機關及有關機關，於本法施行後六個月內劃定海岸地區範圍後公告之；並應於當地縣市政府及鄉鎮市區公所公開展覽，展覽期間不得少於三十日","應會商地方主管機關及有關機關，於本法施行後二年內劃定海岸地區範圍後公告之；並應於當地縣市政府及鄉鎮市區公所公開展覽，展覽期間不得少於十五日","應報請行政院核定後，於本法施行後一年內劃定海岸地區範圍並公告之；並應於中央主管機關網站公開展覽，展覽期間不得少於六十日並登載新聞紙","應由各直轄市、縣（市）主管機關分別劃定其轄區內海岸地區範圍後公告之；並應於當地鄉鎮市區公所公開展覽，展覽期間不得少於四十五日"],"a",
 "第5條：中央主管機關應會商直轄市、縣（市）主管機關及有關機關，於本法施行後六個月內，劃定海岸地區範圍後公告之，並應將劃定結果於當地直轄市或縣（市）政府及鄉（鎮、市、區）公所分別公開展覽；其展覽期間不得少於三十日，並應登載於政府公報、新聞紙，並得以網際網路或其他適當方法廣泛周知；其變更或廢止時亦同。第44條另定中央主管機關應於本法施行後二年內公告實施整體海岸管理計畫。",
 "When must the central authority delimit and announce the coastal zone, and what display period applies?",
 ["In consultation with local authorities and relevant agencies, it must delimit and announce the coastal zone within six months of the Act taking effect, and display the result at local governments and township offices for not less than thirty days","In consultation with local authorities and relevant agencies, it must delimit and announce the coastal zone within two years of the Act taking effect, and display the result at local governments and township offices for not less than fifteen days","Subject to Executive Yuan approval, it must delimit and announce the coastal zone within one year of the Act taking effect, and display it on the central authority's website for not less than sixty days with newspaper publication","Each municipal and county competent authority must delimit and announce the coastal zone within its own jurisdiction, and display the result at the local township offices for not less than forty-five days"],
 "Article 5; Article 44."),

(CM,"第6條",2,"海管法-資料庫",
 "中央主管機關就海岸地區基本資料庫負有何種義務？各機關有何配合義務？",
 ["應會同有關機關建立海岸地區基本資料庫，定期更新資料與發布海岸管理白皮書，並透過網路或其他適當方式公開；除涉及國家安全者外，各有關機關應配合提供必要之資料","應會同有關機關建立海岸地區基本資料庫，每十年發布海岸管理白皮書一次，該資料庫屬機密不得對外公開；各有關機關得視其業務需要決定是否提供相關必要資料","應委託學術研究機構建立海岸地區基本資料庫並代為發布白皮書，中央主管機關僅負監督之責；涉及國家安全之資料仍應由各有關機關全數提供不得保留","應由各直轄市、縣（市）主管機關分別建立轄區資料庫並發布地方海岸管理白皮書，中央不另建置；各有關機關僅於中央主管機關函請時提供必要之資料"],"a",
 "第6條第1項：中央主管機關應會同有關機關建立海岸地區之基本資料庫，定期更新資料與發布海岸管理白皮書，並透過網路或其他適當方式公開，以供海岸研究、規劃、教育、保護及管理等運用。第2項：為建立基本資料庫，中央主管機關得商請有關機關設必要之測站與相關設施，並整合推動維護事宜；除涉及國家安全者外，各有關機關應配合提供必要之資料。",
 "What duties apply to the coastal zone database, and what must other agencies do?",
 ["The central authority must build the database with relevant agencies, update it and issue a coastal management white paper periodically, and publish it online or otherwise; except where national security is involved, agencies must supply the necessary data","The central authority must build the database together with relevant agencies and issue a coastal management white paper once every ten years, the database being classified and never published; agencies may decide for themselves whether to supply the necessary data","The central authority must commission academic institutions to build the database and issue the white paper, retaining only a supervisory role; even national security data must be supplied in full by the agencies concerned","Each municipal and county authority must build its own database and issue a local white paper, with no central database; agencies supply data only when the central authority writes to request it"],
 "Article 6, paragraphs 1 and 2."),

(CM,"第7條",3,"海管法-規劃管理原則",
 "海岸地區之規劃管理原則，包括下列哪些內容？",
 ["優先保護自然海岸並維繫海岸之自然動態平衡；保護海岸自然與文化資產、保全海岸景觀與視域；保育珊瑚礁、藻礁、海草床、河口、潟湖、沙洲、沙丘、沙灘、泥灘、崖岸、岬頭、紅樹林、海岸林等敏感地區","優先開發自然海岸並提高海岸土地之使用強度；促進海岸產業聚落發展、擴大臨海工業區之設置；開發珊瑚礁、藻礁、海草床、河口、潟湖、沙洲、沙丘、沙灘、泥灘、崖岸、岬頭、紅樹林等區位以供遊憩使用","優先劃設海岸防護區並全面興建海岸硬式防護設施；保全海堤結構安全與抽水設施、擴充滯洪池容量；改善珊瑚礁、藻礁、海草床、河口、潟湖、沙洲、沙丘、沙灘、泥灘等地形以利工程施作","優先辦理海岸土地徵收並統一由公部門管理使用；保障漁業權人與養殖業者之既得權益、限制民眾進入；管制珊瑚礁、藻礁、海草床、河口、潟湖、沙洲、沙丘、沙灘、泥灘等區域之學術研究活動"],"a",
 "第7條第1至3款：海岸地區之規劃管理原則包括優先保護自然海岸並維繫海岸之自然動態平衡；保護海岸自然與文化資產，保全海岸景觀與視域，並規劃功能調和之土地使用；保育珊瑚礁、藻礁、海草床、河口、潟湖、沙洲、沙丘、沙灘、泥灘、崖岸、岬頭、紅樹林、海岸林等及其他敏感地區，維護其棲地與環境完整性，並規範人為活動。第1條並揭示確保自然海岸零損失之立法目的。",
 "Which principles govern the planning and management of the coastal zone?",
 ["Giving priority to protecting natural coastline and maintaining its natural dynamic equilibrium; protecting coastal natural and cultural assets and preserving coastal landscape and viewsheds; conserving coral reefs, algal reefs, seagrass beds, estuaries, lagoons, sandbars, dunes, beaches, mudflats, cliffs, headlands, mangroves and coastal forests","Giving priority to developing natural coastline and raising the intensity of coastal land use; promoting coastal industrial clusters and expanding waterfront industrial parks; opening up coral reefs, algal reefs, seagrass beds, estuaries, lagoons, sandbars, dunes, beaches, mudflats, cliffs, headlands and mangroves for recreational and tourism use","Giving priority to designating protection zones and building hard coastal defenses everywhere; securing seawall structures and pumping facilities and expanding detention pond capacity; reshaping coral reefs, algal reefs, seagrass beds, estuaries, lagoons, sandbars, dunes, beaches and mudflats to facilitate construction","Giving priority to expropriating coastal land for unified public management; safeguarding the vested rights of fishing right holders and aquaculture operators while barring public entry; restricting academic research in coral reefs, algal reefs, seagrass beds, estuaries, lagoons, sandbars, dunes, beaches and mudflats"],
 "Article 7, subparagraphs 1-3; Article 1."),

(CM,"第7條",3,"海管法-規劃管理原則",
 "海岸地區之規劃管理原則，尚包括下列哪些內容？",
 ["易致災害之海岸地區應採退縮建築或調適其土地使用；海岸地區應避免新建廢棄物掩埋場，原有場址應納入整體海岸管理計畫檢討，必要時應編列預算逐年移除；並應維護公共通行與公共使用之權益，避免獨占性之使用","易致災害之海岸地區應加高海堤並提高建蔽率以充分利用土地；海岸地區得優先設置廢棄物掩埋場以解決處理量能不足，原有場址應予擴建；並應保障業者專用使用之權益，避免公眾任意進入影響作業","易致災害之海岸地區應全面禁止任何土地使用行為並劃為淨空區；海岸地區之廢棄物掩埋場應於三年內全數關閉並移轉土地所有權；並應維護公共通行權益，但既有獨占性使用得無限期繼續予以保留","易致災害之海岸地區應由政府全數徵收後改為公有並閒置管理；海岸地區新建廢棄物掩埋場應報請行政院專案核准，原有場址免予檢討；並應優先保障原住民族之獨占性使用，限制一般民眾通行"],"a",
 "第7條第4至6款：因應氣候變遷與海岸災害風險，易致災害之海岸地區應採退縮建築或調適其土地使用；海岸地區應避免新建廢棄物掩埋場，原有場址應納入整體海岸管理計畫檢討，必要時應編列預算逐年移除或採行其他改善措施；海岸地區應維護公共通行與公共使用之權益，避免獨占性之使用，並應兼顧原合法權益之保障。第31條並就近岸海域及公有自然沙灘禁止獨占性使用設有具體規範。",
 "What further principles apply to coastal zone planning and management?",
 ["Hazard-prone coastal areas must adopt setback building or adapt their land use; new landfills should be avoided in the coastal zone, with existing sites reviewed in the integrated plan and budgeted for phased removal if necessary; and public passage and public use rights must be preserved, avoiding exclusive use","Hazard-prone coastal areas must raise seawalls and increase building coverage ratios to use the land fully; the coastal zone should host new landfills first to relieve waste treatment shortfalls, with existing sites expanded; and operators' exclusive use rights must be secured against public entry and passage","Hazard-prone coastal areas must ban all land use entirely and be cleared as empty zones; coastal landfills must all close within three years with their land title transferred; and public passage is preserved, though existing exclusive uses may continue indefinitely","Hazard-prone coastal areas must be wholly expropriated into public ownership and left idle; new coastal landfills require special Executive Yuan approval while existing sites need no review; and indigenous exclusive use is given priority over general public passage"],
 "Article 7, subparagraphs 4-6; Article 31."),

(CM,"第8條",3,"海管法-整體海岸管理計畫",
 "中央主管機關擬訂之整體海岸管理計畫，其計畫內容應包括哪些事項？",
 ["計畫範圍、計畫目標、自然與人文資源、社會與經濟條件、氣候變遷調適策略、整體海岸保護防護及永續利用之議題原則與對策、保護區與防護區之區位及其計畫擬訂機關與期限之指定","計畫範圍、計畫目標、土地權屬清冊、地價評估基準、開發利益回饋比率、海岸土地標售與招商作業原則、保護區與防護區內既有建物之拆遷補償標準及其執行時程之指定","計畫範圍、計畫目標、漁業權設定現況、養殖許可核發數量、海域遊憩活動管理規則、港區航道疏濬及沙源調配原則、防護工程受益費之徵收費率與分攤比例之個別指定","計畫範圍、計畫目標、軍事管制區位置、海岸監控設施配置、偷渡走私熱點分析、海岸巡防勤務規劃與人力配置原則、保護區與防護區內軍事設施之保密等級及管制強度指定"],"a",
 "第8條：為保護、防護、利用及管理海岸地區土地，中央主管機關應擬訂整體海岸管理計畫，其內容應包括計畫範圍、計畫目標、自然與人文資源、社會與經濟條件、氣候變遷調適策略、整體海岸保護防護及永續利用之議題原則與對策、保護區與防護區之區位及其計畫擬訂機關與期限之指定、劃設海岸管理須特別關注之特定區位等事項。第9條並定其擬訂與審議程序。",
 "What must the integrated coastal zone management plan contain?",
 ["Plan scope; plan objectives; natural and cultural resources; social and economic conditions; climate change adaptation strategy; issues, principles and strategies for overall coastal protection, defense and sustainable use; and the location of protection and defense zones with the agencies and deadlines for drafting their plans","Plan scope; plan objectives; a detailed land ownership register; land price appraisal bases; the development benefit feedback ratio; principles for tendering, standing and marketing coastal land parcels; and demolition compensation standards and implementation timetables for existing buildings inside the designated protection and defense zones","Plan scope; plan objectives; the status of fishing rights; the number of aquaculture permits issued; management rules for marine recreation; principles for channel dredging and sand allocation; and the rates and apportionment of coastal defense works benefit charges","Plan scope; plan objectives; the location of military control areas; the layout of coastal surveillance facilities; analysis of smuggling hotspots; coast guard patrol planning and manpower deployment; and the security classification of military installations in the zones"],
 "Article 8; Article 9."),

(CM,"第8條",2,"海管法-特定區位",
 "整體海岸管理計畫內容中，除保護區與防護區之指定外，尚應包括哪些事項？",
 ["劃設海岸管理須特別關注之特定區位；有關海岸之自然、歷史、文化、社會、研究、教育及景觀等特定重要資源之區位、保護、使用及復育原則；發展遲緩或環境劣化地區之發展、復育及治理原則","劃設可供標售或設定地上權之特定區位；有關海岸之自然、歷史、文化、社會、研究、教育及景觀等資源之商業利用授權原則；發展遲緩地區之招商引資、產業轉型及租稅減免優惠原則","劃設得免經許可逕行開發之特定區位；有關海岸之自然、歷史、文化、社會、研究及景觀資源之私有化移轉原則；環境劣化地區之土地變更編定、容積移轉及開發強度提高原則","劃設軍事管制與海防勤務之特定區位；有關海岸之自然、歷史、文化、社會、研究及景觀資源之保密分級原則；發展遲緩或環境劣化地區之人口遷移、聚落廢村及土地徵收原則"],"a",
 "第8條第8至10款：整體海岸管理計畫應包括劃設海岸管理須特別關注之特定區位；有關海岸之自然、歷史、文化、社會、研究、教育及景觀等特定重要資源之區位、保護、使用及復育原則；發展遲緩或環境劣化地區之發展、復育及治理原則。第11條第2項並定明主管機關對指定之發展遲緩或環境劣化地區，得協調相關機關輔導其傳統文化保存、生態保育、資源復育及社區發展整合規劃事項。第25條所稱特定區位即依本條劃設。",
 "Besides designating protection and defense zones, what else must the integrated plan cover?",
 ["Designating specific locations needing particular attention; the location, protection, use and restoration principles for important natural, historical, cultural, social, research, educational and landscape resources; and the development, restoration and governance principles for lagging or degraded areas","Designating specific locations available for sale or superficies rights; principles for licensing commercial use of natural, historical, cultural, social, research, educational and landscape resources; and investment attraction, industrial transition and tax relief principles for lagging areas","Designating specific locations that may be developed without any permit; principles for privatizing natural, historical, cultural, social, research and landscape resources; and principles for rezoning, floor area transfer and higher development intensity in degraded areas","Designating specific locations for military control and coastal defense duties; security classification principles for natural, historical, cultural, social, research and landscape resources; and principles for population relocation, village abandonment and expropriation in lagging or degraded areas"],
 "Article 8, subparagraphs 8-10; Articles 11 and 25."),

(CM,"第9條",3,"海管法-計畫擬訂程序",
 "整體海岸管理計畫之擬訂與審議程序有何要求？公告實施期限為何？",
 ["應廣詢意見並以合議方式審議，其學者專家及民間團體之代表人數不得少於二分之一；送審前應公開展覽三十日及舉行公聽會；報請行政院核定後，中央主管機關應於接到核定公文之日起四十天內公告實施","應廣詢意見並以合議方式審議，其學者專家及民間團體之代表人數不得少於三分之一；送審前應公開展覽十五日及舉行說明會；報請行政院備查後，中央主管機關應於接到備查公文之日起六十天內公告實施","應由中央主管機關逕行擬訂而免經審議程序，僅須諮詢相關部會意見；送審前應公開展覽六十日並登報周知；報請立法院同意後，中央主管機關應於接到同意函之日起三十天內公告實施","應委由學術機構代為擬訂並以合議方式審議，其機關代表人數不得少於二分之一；送審前應公開展覽三十日及舉行聽證；報請行政院核定後，由各地方主管機關於九十天內分別公告實施"],"a",
 "第9條第1項：整體海岸管理計畫之擬訂，應邀集學者、專家、相關部會、中央民意機關、民間團體等舉辦座談會或其他適當方法廣詢意見，並遴聘（派）學者、專家、機關及民間團體代表以合議方式審議，其學者、專家及民間團體之代表人數不得少於二分之一，報請行政院核定後公告實施。第2項：送審議前應公開展覽三十日及舉行公聽會。第4項：核定後應於接到核定公文之日起四十天內公告實施，並函送地方公開展覽不得少於三十日。",
 "What procedure applies to drafting and reviewing the integrated plan, and when must it be announced?",
 ["Opinions must be canvassed widely and review is collegial, with scholars, experts and civil group representatives not fewer than one half; before review it must be displayed for thirty days with a public hearing; after Executive Yuan approval it must be announced within forty days of receiving the approval","Opinions must be canvassed and review is collegial, with scholars, experts and civil group representatives not fewer than one third; before review it must be displayed for fifteen days with a briefing session; after filing with the Executive Yuan it must be announced within sixty days of receiving the filing reply","The central authority may draft it directly without any review procedure, merely consulting the relevant ministries; before review it must be displayed for sixty days with newspaper notice; after Legislative Yuan consent it must be announced within thirty days","Academic institutions may be commissioned to draft it and review is collegial, with agency representatives not fewer than one half; before review it must be displayed for thirty days with a hearing; after Executive Yuan approval local authorities announce it within ninety days"],
 "Article 9, paragraphs 1, 2 and 4."),

(CM,"第10條",3,"海管法-計畫擬訂機關",
 "一級與二級海岸保護計畫之擬訂機關分別為何？認定有疑義時如何處理？",
 ["一級海岸保護計畫由中央目的事業主管機關擬訂，涉及二以上目的事業者由主要業務之中央目的事業主管機關會商擬訂；二級由直轄市、縣（市）主管機關擬訂；等級認定有疑義者得由中央主管機關協調指定或逕行擬訂","一級海岸保護計畫由中央主管機關逕行擬訂，涉及二以上目的事業者由行政院指定機關擬訂；二級由中央目的事業主管機關擬訂；保護區等級認定有疑義者一律由行政院協調指定或逕行交由地方主管機關擬訂","一級海岸保護計畫由直轄市、縣（市）主管機關擬訂後報中央核定；二級由鄉（鎮、市、區）公所擬訂；等級認定有疑義者得由中央目的事業主管機關協調指定，中央主管機關不得逕行擬訂","一級與二級海岸保護計畫均由中央目的事業主管機關擬訂，地方主管機關僅負執行管理之責；等級認定有疑義者應報請立法院決議指定，中央主管機關不得協調指定或逕行擬訂"],"a",
 "第10條第1項第1款：一級海岸保護計畫由中央目的事業主管機關擬訂，涉及二以上目的事業者，由主要業務之中央目的事業主管機關會商有關機關擬訂；二級海岸保護計畫由直轄市、縣（市）主管機關擬訂，但跨二以上行政區域或涉及二以上目的事業者，由相關地方主管機關協調擬訂；保護區等級及計畫擬訂機關之認定有疑義者，得由中央主管機關協調指定或逕行擬訂。第3項並定明涉原住民族地區應會商原住民族委員會擬訂。",
 "Who drafts first- and second-class coastal protection plans, and what if the classification is unclear?",
 ["First-class plans are drafted by the central industry authority, or by the one with the main business in consultation where two or more are involved; second-class plans by municipal or county authorities; where classification is unclear the central authority may coordinate a designation or draft the plan itself","First-class plans are drafted by the central competent authority itself, or by an agency designated by the Executive Yuan where two or more industries are involved; second-class plans by central industry authorities; unclear protection zone classifications are always settled and designated by the Executive Yuan","First-class plans are drafted by municipal or county authorities and approved centrally; second-class plans by township offices; where classification is unclear the central industry authority may coordinate a designation but the central authority may not draft the plan","Both first- and second-class plans are drafted by central industry authorities, with local authorities only implementing them; unclear classifications must be settled by a Legislative Yuan resolution, and the central authority may neither designate nor draft"],
 "Article 10, paragraphs 1 and 3."),

(CM,"第10條",2,"海管法-防護計畫擬訂",
 "一級與二級海岸防護計畫之擬訂機關為何？涉及原住民族地區時應如何辦理？",
 ["一級海岸防護計畫由中央目的事業主管機關協調有關機關後擬訂；二級由直轄市、縣（市）主管機關擬訂；如涉原住民族地區，各級主管機關應會商原住民族委員會擬訂","一級海岸防護計畫由中央水利主管機關逕行擬訂並公告；二級由鄉（鎮、市、區）公所擬訂；如涉原住民族地區，各級主管機關應報請行政院核定後始得擬訂相關計畫","一級海岸防護計畫由中央主管機關會商地方後擬訂；二級由中央目的事業主管機關擬訂；如涉原住民族地區，應由原住民族委員會單獨擬訂該區域之海岸防護計畫內容","一級與二級海岸防護計畫均由直轄市、縣（市）主管機關擬訂；如涉原住民族地區，各級主管機關得逕行擬訂而免會商，僅須於公告後通知原住民族委員會備查"],"a",
 "第10條第1項第2款：一級海岸防護計畫由中央目的事業主管機關協調有關機關後擬訂；二級海岸防護計畫由直轄市、縣（市）主管機關擬訂；防護區等級及其計畫擬訂機關之認定有疑義者，得由中央主管機關協調指定。第3項：第1項計畫之擬訂及海岸保護區或海岸防護區之劃設，如涉原住民族地區，各級主管機關應會商原住民族委員會擬訂。第14條第2項並定明海岸侵蝕等前四款之目的事業主管機關為水利主管機關。",
 "Who drafts first- and second-class coastal defense plans, and what applies in indigenous areas?",
 ["First-class defense plans are drafted by the central industry authority after coordinating with relevant agencies; second-class plans by municipal or county authorities; where indigenous areas are involved, authorities must draft in consultation with the Council of Indigenous Peoples","First-class defense plans are drafted and announced by the central water authority directly; second-class plans by township offices; where indigenous areas are involved, authorities must obtain Executive Yuan approval before drafting any plan","First-class defense plans are drafted by the central competent authority after consulting the local authorities; second-class plans by the central industry authorities; where indigenous areas are involved, the Council of Indigenous Peoples drafts that area's defense plan alone","Both first- and second-class defense plans are drafted by municipal or county authorities; where indigenous areas are involved, authorities may draft without consultation and merely notify the Council of Indigenous Peoples after announcement"],
 "Article 10, paragraphs 1 and 3; Article 14."),

(CM,"第11條",2,"海管法-景觀區與劣化地區",
 "依整體海岸管理計畫劃定之重要海岸景觀區及指定之發展遲緩或環境劣化地區，應如何處理？",
 ["重要海岸景觀區應訂定都市設計準則，以規範其土地使用配置、建築物及設施高度與其他景觀要素；發展遲緩或環境劣化地區，主管機關得協調相關機關輔導其傳統文化保存、生態保育、資源復育及社區發展整合規劃事項","重要海岸景觀區應一律禁止任何開發及建築行為並劃定為零開發管制區；發展遲緩或環境劣化地區，主管機關應逕行辦理土地徵收並遷移當地全部居民，其所受損失依土地徵收條例規定給予補償及救濟","重要海岸景觀區應提高其法定容積率以獎勵民間投資開發；發展遲緩或環境劣化地區，主管機關得放寬開發強度管制並提供租稅減免，以吸引業者進駐並改善地方之整體經濟條件","重要海岸景觀區應由中央主管機關逕行編定為國家風景區；發展遲緩或環境劣化地區，主管機關應停止一切公共建設投資，俟環境自然復育完成後再行檢討其土地使用之管制方式"],"a",
 "第11條第1項：依整體海岸管理計畫劃定之重要海岸景觀區，應訂定都市設計準則，以規範其土地使用配置、建築物及設施高度與其他景觀要素。第2項：依整體海岸管理計畫指定之發展遲緩或環境劣化地區，主管機關得協調相關機關輔導其傳統文化保存、生態保育、資源復育及社區發展整合規劃事項。第8條第9、10款為其計畫依據。",
 "How are important coastal landscape areas and lagging or degraded areas to be handled?",
 ["Important landscape areas must have urban design guidelines governing land use layout, building and facility heights and other landscape elements; for lagging or degraded areas the authority may coordinate guidance on cultural preservation, ecological conservation, resource restoration and community development","Important landscape areas must ban all construction and be zoned for zero development; for lagging or degraded areas the authority must expropriate the land and relocate residents, with compensation under the Land Expropriation Act","Important landscape areas must have their statutory floor area ratio and building coverage ratio raised to reward and attract private investment; for lagging or degraded areas the authority may relax development intensity controls and offer tax relief and subsidies to attract operators and improve the local economy","Important landscape areas must be designated national scenic areas by the central authority; for lagging or degraded areas the authority must halt all public works investment until natural restoration is complete"],
 "Article 11; Article 8."),

(CM,"第12條",3,"海管法-一級保護區",
 "海岸地區具有下列哪些情形之一者，應劃設為一級海岸保護區？",
 ["重要水產資源保育地區；珍貴稀有動植物重要棲地及生態廊道；特殊景觀資源及休憩地區；重要濱海陸地或水下文化資產地區；特殊自然地形地貌地區；生物多樣性資源豐富地區；地下水補注區","重要工業區位及港埠腹地；珍貴稀有礦產與砂石資源蘊藏地區；特殊觀光遊憩開發潛力地區；重要濱海陸地之都市計畫擴大區；填海造地適宜地區；土地權屬單純且完整地區；地下水超抽補注區","重要軍事管制與雷達站設置地區；珍貴稀有動植物已滅絕而待復育之地區；特殊景觀資源已遭破壞地區；重要濱海陸地之既有聚落區；特殊自然地形已消失地區；生物多樣性資源貧乏地區；地下水污染管制區","重要漁業權設定與養殖生產地區；珍貴稀有水產種苗培育及放流地區；特殊海域遊憩活動經營地區；重要濱海陸地之遊艇港區；特殊人工地形地貌設施區；生物多樣性復育試驗地區；地下水抽用登記區"],"a",
 "第12條第1項：海岸地區具有下列情形之一者，應劃設為一級海岸保護區，其餘有保護必要之地區得劃設為二級海岸保護區：重要水產資源保育地區、珍貴稀有動植物重要棲地及生態廊道、特殊景觀資源及休憩地區、重要濱海陸地或水下文化資產地區、特殊自然地形地貌地區、生物多樣性資源豐富地區、地下水補注區、經依法劃設之國際級及國家級重要濕地及其他重要之海岸生態系統、其他依法律規定應予保護之重要地區。",
 "Which situations require designation as a first-class coastal protection zone?",
 ["Important aquatic resource conservation areas; key habitats and ecological corridors of rare and precious flora and fauna; special landscape resource and recreation areas; important coastal land or underwater cultural heritage areas; special natural landform areas; areas rich in biodiversity resources; and groundwater recharge areas","Important industrial sites and port hinterlands; areas holding rare and precious minerals and aggregates; areas with special tourism development potential; expansion areas of coastal urban plans; areas suitable for land reclamation; areas of simple and intact land ownership; and over-pumped groundwater areas","Important military control and radar station areas; areas where rare flora and fauna are extinct and await restoration; areas where special landscape resources are already destroyed; existing settlements on important coastal land; areas whose landforms have vanished; biodiversity-poor areas; and groundwater pollution control areas","Important areas of established fishing rights and aquaculture production; areas for breeding and releasing rare aquatic fry; areas operating special marine recreation activities; yacht harbor areas on important coastal land; special artificial landform facility areas; biodiversity restoration trial areas; and registered groundwater abstraction areas"],
 "Article 12, paragraph 1."),

(CM,"第12條",3,"海管法-一級保護區管制",
 "一級海岸保護區之使用管制原則為何？原合法使用不合保護計畫者如何處理？",
 ["應禁止改變其資源條件之使用，但依海岸保護計畫為相容、維護、管理及學術研究之使用，或為國家安全、公共安全需要經中央主管機關許可者，不在此限；原合法使用不合計畫者，地方主管機關得限期令其變更使用或遷移，所受損失應予適當補償","應禁止一切人為活動、開發及進入行為，並無任何例外或但書規定；原合法使用不合海岸保護計畫者，地方主管機關應逕行撤銷其許可並命立即停止使用，因此所受之全部損失均由使用人自行承擔，主管機關不負任何補償或救濟責任","得自由改變其資源條件之使用，僅須事前報請地方主管機關備查；原合法使用不合計畫者，得繼續為原來之使用至權利存續期間屆滿為止，主管機關不得令其變更使用或遷移，亦不生補償問題","應禁止改變其資源條件之使用，但經目的事業主管機關同意者不在此限；原合法使用不合計畫者，應於計畫公告後六個月內自行停止使用並拆除設施，逾期由主管機關代為拆除並向其求償費用"],"a",
 "第12條第2項：一級海岸保護區應禁止改變其資源條件之使用，但依海岸保護計畫為相容、維護、管理及學術研究之使用，或為國家安全、公共安全需要經中央主管機關許可者，不在此限。第3項：一級海岸保護區內原合法使用不合海岸保護計畫者，直轄市、縣（市）主管機關得限期令其變更使用或遷移，其所受之損失應予適當補償；在令其變更使用、遷移前，得為原來之合法使用或改為妨礙目的較輕之使用。第32條並定有違反者之罰則。",
 "How is use controlled in a first-class protection zone, and what happens to lawful existing uses that conflict?",
 ["Uses changing its resource conditions are prohibited, except compatible, maintenance, management and academic research uses under the protection plan, or uses permitted by the central authority for national or public safety; conflicting lawful existing uses may be ordered changed or relocated with appropriate compensation","All human activity and entry are prohibited with no exception whatsoever; conflicting lawful existing uses have their permits revoked and must stop at once, with all resulting losses borne by the user and no compensation payable by the authority","Resource conditions may be freely changed subject only to prior filing with the local authority; conflicting lawful existing uses may continue until their rights expire, and the authority may not order any change or relocation nor pay compensation","Uses changing the area's resource conditions are prohibited unless the relevant industry authority consents in writing; conflicting lawful existing uses must cease and be demolished within six months of the plan's announcement, failing which the authority demolishes them itself and recovers all of the costs incurred"],
 "Article 12, paragraphs 2 and 3; Article 32."),

(CM,"第13條",2,"海管法-保護計畫內容",
 "海岸保護計畫應載明哪些事項？依其他法律納入保護之地區如何處理？",
 ["應載明保護標的及目的、海岸保護區之範圍、禁止及相容之使用、保護監測與復育措施及方法、事業及財務計畫等事項；依其他法律規定納入保護之地區符合整體海岸管理計畫基本管理原則者，從其規定，免依第十條及第十二條辦理","應載明保護標的及目的、海岸保護區之範圍、開發強度與容積獎勵、土地徵收與補償標準、招商及財務計畫等事項；依其他法律規定納入保護之地區，仍應一律重新依第十條及第十二條規定辦理劃設及計畫擬訂程序","應載明保護標的及目的、海岸防護設施之種類規模及配置、海岸災害風險分析概要、防護措施及方法等事項；依其他法律規定納入保護之地區，其保護地區名稱及管理事項應改依本法規定辦理並重新公告","應載明保護標的及目的、既有建物拆遷時程、居民安置計畫、漁業權補償金額等事項；依其他法律規定納入保護之地區，應由中央主管機關逕行廢止原有保護規定後，再依本法重新劃設保護區"],"a",
 "第13條第1項：海岸保護計畫應載明保護標的及目的、海岸保護區之範圍、禁止及相容之使用、保護監測與復育措施及方法、事業及財務計畫及其他與海岸保護計畫有關之事項。第2項：依其他法律規定納入保護之地區，符合整體海岸管理計畫基本管理原則者，其保護之地區名稱、內容、劃設程序、辦理機關及管理事項從其規定，免依第10條及第12條規定辦理。第3項並定明必要時主管機關仍得擬訂禁止及相容使用事項之保護計畫。",
 "What must a coastal protection plan state, and how are areas protected under other laws treated?",
 ["It must state the protection target and purpose, the zone boundary, prohibited and compatible uses, protection, monitoring and restoration measures, and the operational and financial plan; areas protected under other laws that meet the basic principles follow those laws and are exempt from Articles 10 and 12","It must state the protection target and purpose, the zone boundary, development intensity and floor area incentives, expropriation and compensation standards, and the investment and financial plan; areas protected under other laws must still be redesignated and replanned under Articles 10 and 12 of this Act","It must state the protection target and purpose, the types, scale and layout of defense facilities, a hazard risk analysis summary, and defense measures and methods; areas protected under other laws must have their names and management matters redone under this Act","It must state the protection target and purpose, the demolition schedule for existing buildings, a resident resettlement plan, and fishing right compensation amounts; areas protected under other laws must have that protection revoked before redesignation under this Act"],
 "Article 13, paragraphs 1-3."),

(CM,"第14條",3,"海管法-海岸防護區",
 "海岸地區有哪些情形者得劃設為一級或二級海岸防護區？其目的事業主管機關為何？",
 ["海岸侵蝕、洪氾溢淹、暴潮溢淹、地層下陷及其他潛在災害；其中第一款至第四款之目的事業主管機關為水利主管機關，第五款之目的事業主管機關依其他法律規定或由中央主管機關協調指定","海岸侵蝕、洪氾溢淹、暴潮溢淹、地層下陷及其他潛在災害；其中第一款至第四款之目的事業主管機關為環境保護主管機關，第五款之目的事業主管機關一律由行政院逕行指定並公告","土壤液化、山崩地滑、海嘯溢淹、土石流及其他潛在災害；其中第一款至第四款之目的事業主管機關為水利主管機關，第五款之目的事業主管機關由地方主管機關協調指定後公告","海岸侵蝕、漁業衰退、觀光沒落、聚落老化及其他潛在風險；其中第一款至第四款之目的事業主管機關為農業主管機關，第五款之目的事業主管機關由中央主管機關報請立法院指定"],"a",
 "第14條第1項：為防治海岸災害，預防海水倒灌、國土流失，保護民眾生命財產安全，海岸地區有海岸侵蝕、洪氾溢淹、暴潮溢淹、地層下陷或其他潛在災害情形之一者，得視其嚴重情形劃設為一級或二級海岸防護區，並分別訂定海岸防護計畫。第2項：第1款至第4款之目的事業主管機關為水利主管機關。第4項：第5款之目的事業主管機關依其他法律規定或由中央主管機關協調指定之。",
 "Which situations allow designation as a coastal defense zone, and who is the responsible industry authority?",
 ["Coastal erosion, flood inundation, storm surge inundation, land subsidence and other potential hazards; for the first four the responsible industry authority is the water authority, and for the fifth it is set by other law or coordinated and designated by the central authority","Coastal erosion, flood inundation, storm surge inundation, land subsidence and other potential hazards; for the first four the responsible industry authority is the environmental authority, and for the fifth it is designated and announced by the Executive Yuan","Soil liquefaction, landslides, tsunami inundation, debris flows and other potential hazards; for the first four the responsible industry authority is the water authority, and for the fifth it is coordinated and announced by local competent authorities","Coastal erosion, fishery decline, tourism decline, settlement ageing and other potential risks; for the first four the responsible industry authority is the agriculture authority, and for the fifth it is designated by the Legislative Yuan on the central authority's request"],
 "Article 14, paragraphs 1, 2 and 4."),

(CM,"第14條",2,"海管法-防護措施權責",
 "第十四條第一項第一款海岸侵蝕因興辦事業計畫實施所造成或其他法令已有分工權責規定者，其防護措施應由誰辦理？",
 ["由各該興辦事業計畫之目的事業主管機關辦理","由中央水利主管機關統一辦理並負擔全部經費","由直轄市、縣（市）主管機關逕行辦理及編列預算","由中央主管機關協調指定其他機關代為辦理防護"],"a",
 "第14條第3項：第1項第1款（海岸侵蝕）因興辦事業計畫之實施所造成或其他法令已有分工權責規定者，其防護措施由各該興辦事業計畫之目的事業主管機關辦理。第2項則定明第1款至第4款之目的事業主管機關原則為水利主管機關；第24條並規定海岸防護設施兼有道路、水門、起卸貨場等其他設施效用時，由該其他設施主管機關實施工程並維護管理。",
 "Who carries out defense measures where erosion is caused by an undertaking or where other laws allocate responsibility?",
 ["The industry authority responsible for that particular undertaking's plan","The central water authority alone, bearing the full cost of the works","The municipal or county competent authority, budgeting for it directly","Another agency coordinated and designated by the central competent authority"],
 "Article 14, paragraph 3; Articles 2 and 24."),

(CM,"第15條",3,"海管法-防護計畫內容",
 "海岸防護計畫應載明哪些事項？",
 ["海岸災害風險分析概要、防護標的及目的、海岸防護區範圍、禁止及相容之使用、防護措施及方法、海岸防護設施之種類規模及配置、事業及財務計畫等事項","土地權屬與地價清冊、防護標的及目的、海岸防護區範圍、開發強度與容積率、招商引資策略、海岸防護設施之採購方式與廠商資格、營運移轉計畫等事項","漁業權補償標準、防護標的及目的、海岸防護區範圍、既有建物拆遷時程、居民安置方案、海岸防護設施之保險額度與理賠程序、稅賦減免計畫等事項","軍事管制強度分級、防護標的及目的、海岸防護區範圍、巡防勤務配置、監控設施位置、海岸防護設施之保密等級與管制措施、人力訓練計畫等事項"],"a",
 "第15條第1項：海岸防護計畫應載明海岸災害風險分析概要、防護標的及目的、海岸防護區範圍、禁止及相容之使用、防護措施及方法、海岸防護設施之種類規模及配置、事業及財務計畫及其他與海岸防護計畫有關之事項。第33條並對在海岸防護區內違反該計畫所定禁止使用者，處新臺幣三萬元以上十五萬元以下罰鍰。",
 "What must a coastal defense plan state?",
 ["A coastal hazard risk analysis summary, the defense target and purpose, the defense zone boundary, prohibited and compatible uses, defense measures and methods, the types, scale and layout of defense facilities, and the operational and financial plan","A land ownership and price register, the defense target and purpose, the defense zone boundary, development intensity and floor area ratio, an investment attraction strategy, procurement methods and contractor qualifications, and a build-operate-transfer plan","Fishing right compensation standards, the defense target and purpose, the defense zone boundary, a demolition schedule for existing buildings, a resident resettlement scheme, insurance limits and claim procedures, and a tax relief plan","Military control classification levels, the defense target and purpose, the defense zone boundary, patrol duty deployment, surveillance facility locations, the security classification and control measures for facilities, and a personnel training plan"],
 "Article 15, paragraph 1; Article 33."),

(CM,"第15條",2,"海管法-防護與保護競合",
 "海岸防護區中涉及海岸保護區者，其海岸防護計畫之訂定應如何處理？",
 ["應配合其生態環境保育之特殊需要，避免海岸防護設施破壞或減損海岸保護區之環境、生態、景觀及人文價值，並徵得核定公告之海岸保護計畫擬訂機關同意；無海岸保護計畫者，應徵得海岸保護區目的事業主管機關同意","應以防災工程施作需求為最優先考量，於必要時得逕行變更或廢止該重疊範圍內之海岸保護計畫，並於工程完工後通知原海岸保護計畫擬訂機關備查，無海岸保護計畫者則免辦理任何徵詢或同意程序","應由中央主管機關逕行裁決應以保護或防護為優先，計畫擬訂機關無須徵得任何機關同意；無海岸保護計畫者，應報請行政院指定主辦機關後始得訂定海岸防護計畫之內容","應將該重疊範圍自海岸防護區中排除而不得訂定防護計畫，僅得於海岸保護區外圍施作防護設施；無海岸保護計畫者，得逕行於重疊範圍內施作各類海岸防護設施"],"a",
 "第15條第2項：海岸防護區中涉及第12條第1項海岸保護區者，海岸防護計畫之訂定，應配合其生態環境保育之特殊需要，避免海岸防護設施破壞或減損海岸保護區之環境、生態、景觀及人文價值，並徵得依第16條第3項規定核定公告之海岸保護計畫擬訂機關同意；無海岸保護計畫者，應徵得海岸保護區目的事業主管機關同意。",
 "How must a defense plan be drawn where the defense zone overlaps a protection zone?",
 ["It must accommodate the special needs of ecological conservation, avoid facilities damaging or diminishing the zone's environmental, ecological, landscape and cultural values, and obtain the consent of the agency that drafted the announced protection plan, or of the industry authority where no such plan exists","Disaster prevention needs take priority, so the protection plan within that area may be altered or repealed directly, with the drafting agency merely notified after completion, and no consultation at all where no protection plan exists","The central competent authority decides directly whether protection or defense prevails, and the drafting agency needs no other agency's consent at all; where no protection plan exists, the Executive Yuan must designate a lead agency before the coastal defense plan may be drawn up and publicly announced","The overlapping area must be excluded from the defense zone so that no defense plan may cover it, with works permitted only outside the protection zone; where no protection plan exists, works may be built freely in the overlap"],
 "Article 15, paragraph 2; Article 16."),

(CM,"第16條",3,"海管法-公展與公告",
 "海岸保護計畫、海岸防護計畫之公開展覽、審議及公告程序有何規定？",
 ["擬訂機關應公開展覽三十日及舉行公聽會，人民或團體得於展覽期間以書面提出意見，其參採情形併同計畫報請中央主管機關審議，並應以書面答覆採納情形及理由；核定後應於接到核定公文之日起四十天內公告實施","擬訂機關應公開展覽十五日及舉行說明會，人民或團體得於展覽期間以口頭提出意見，毋須記載其參採情形，亦不必書面答覆；核定後應於接到核定公文之日起九十天內公告實施並函送地方展覽","擬訂機關得免公開展覽而逕送中央主管機關審議，僅須將審議結果登載政府公報；核定後應於接到核定公文之日起六十天內公告實施，並由地方主管機關自行決定是否辦理公開展覽","擬訂機關應公開展覽六十日並舉行聽證，人民或團體之意見應全數採納並修正計畫內容；核定後應於接到核定公文之日起三十天內公告實施，展覽期間不得少於十五日"],"a",
 "第16條第1項：擬訂機關應將海岸保護計畫、海岸防護計畫公開展覽三十日及舉行公聽會，並登載於政府公報、新聞紙及網際網路；任何人民或團體得於公開展覽期間內以書面載明姓名或名稱及地址向擬訂機關提出意見，其參採情形由擬訂機關併同計畫報請中央主管機關審議，並應針對民眾所提意見以書面答覆採納情形並記載其理由。第3項：核定後應於接到核定公文之日起四十天內公告實施，並函送地方公開展覽不得少於三十日，由地方主管機關實施管理。第4項並定明應辦理而未辦理者，上級主管機關得逕為辦理。",
 "What display, review and announcement procedures apply to coastal protection and defense plans?",
 ["The drafting agency must display the plan for thirty days and hold a public hearing; written opinions may be submitted during the display, their treatment reported with the plan to the central authority for review, with written replies giving reasons; the plan must be announced within forty days of approval","The drafting agency must display the plan for fifteen days and hold a briefing session; opinions may be given orally, their treatment need not be recorded and no written reply of any kind is needed; the plan must be announced within ninety days of approval and sent for local public display and inspection","The drafting agency may skip the display and send the plan straight for central review, publishing only the result in the gazette; the plan must be announced within sixty days of approval, with local display left to the local authority's discretion","The drafting agency must display the plan for sixty days and hold a hearing, adopting every opinion submitted and amending the plan accordingly; the plan must be announced within thirty days of approval, with display for not less than fifteen days"],
 "Article 16, paragraphs 1, 3 and 4."),

(CM,"第17條",3,"海管法-審議核定",
 "海岸保護計畫及海岸防護計畫之審議核定程序為何？審議委員組成有何要求？",
 ["中央主管機關擬訂之保護計畫由其會商有關機關審議後報行政院核定；中央目的事業主管機關擬訂者送中央主管機關審議核定；防護計畫由中央目的事業主管機關擬訂者送中央主管機關審議後報行政院核定；審議應以合議方式為之，學者專家及民間團體代表人數不得少於二分之一","中央主管機關擬訂之保護計畫由行政院逕行核定無須審議；中央目的事業主管機關擬訂者送行政院審議核定；防護計畫一律由中央目的事業主管機關自行核定後報中央主管機關備查；審議委員應全數由各級機關代表擔任，不得遴聘學者、專家或民間團體之代表","所有海岸保護計畫及海岸防護計畫，一律由直轄市、縣（市）主管機關審議並自行核定後公告；中央主管機關僅於發生爭議時介入協調；審議應以合議方式為之，機關代表人數不得少於三分之二，學者專家僅具列席陳述意見之地位","所有海岸保護計畫及海岸防護計畫，一律送請立法院審查通過後始生效力；中央主管機關僅負彙整及送件之責；審議應以合議方式為之，學者專家及民間團體代表人數不得少於三分之一，並應由行政院逐案指定委員名單"],"a",
 "第17條第1項：海岸保護計畫由中央主管機關擬訂者，由其會商有關機關審議後報請行政院核定；中央目的事業主管機關擬訂者，送請中央主管機關審議核定；地方主管機關擬訂者，送請中央目的事業主管機關核轉中央主管機關審議核定。海岸防護計畫由中央目的事業主管機關擬訂者，送請中央主管機關審議後報請行政院核定；地方主管機關擬訂者，送請中央目的事業主管機關核轉中央主管機關審議核定。第2項：審議應遴聘（派）學者、專家、機關及民間團體代表以合議方式為之，其學者專家及民間團體之代表人數不得少於二分之一。",
 "How are coastal protection and defense plans reviewed and approved, and how is the review body composed?",
 ["Protection plans drafted by the central authority are reviewed by it with relevant agencies and approved by the Executive Yuan; those drafted by central industry authorities go to the central authority for review and approval; defense plans drafted by central industry authorities are reviewed centrally then approved by the Executive Yuan; review is collegial with scholars, experts and civil groups not fewer than one half","Protection plans drafted by the central competent authority are approved by the Executive Yuan without any review at all; those drafted by central industry authorities go directly to the Executive Yuan for review and approval; defense plans are approved by the central industry authorities themselves and merely filed with the central authority; all reviewers must be agency representatives, with no scholars, experts or civil group representatives appointed","All protection and defense plans are reviewed and approved by municipal or county authorities and then announced; the central authority intervenes only in disputes; review is collegial with agency representatives not fewer than two thirds, scholars merely attending to state opinions","All protection and defense plans take effect only after Legislative Yuan approval; the central authority merely compiles and forwards them; review is collegial with scholars, experts and civil groups not fewer than one third, the members being designated case by case by the Executive Yuan"],
 "Article 17, paragraphs 1 and 2."),

(CM,"第18條",2,"海管法-通盤檢討",
 "整體海岸管理計畫、海岸保護計畫及海岸防護計畫公告實施後，應多久通盤檢討一次？何種情形得隨時檢討？",
 ["應視海岸情況每五年通盤檢討一次並作必要之變更；但為興辦重要或緊急保育措施、為防治重大或緊急災害、政府為促進公共福祉或興辦國防所辦理之必要性公共建設者，得隨時檢討之","應視海岸情況每十年通盤檢討一次並作必要之變更；但為興辦重要或緊急保育措施、為防治重大或緊急災害、政府為促進公共福祉或興辦國防所辦理之必要性公共建設者，得隨時檢討之","應視海岸情況每三年通盤檢討一次並作必要之變更；但僅於發生重大海岸災害致原計畫顯不適用時，始得由中央主管機關報請行政院核准後隨時檢討並辦理變更","應視海岸情況每五年通盤檢討一次並作必要之變更；計畫一經公告實施即不得於檢討期間外任意變更，縱使發生重大災害或國防需要，仍應俟下次通盤檢討時一併處理"],"a",
 "第18條第1項：整體海岸管理計畫、海岸保護計畫、海岸防護計畫經公告實施後，擬訂機關應視海岸情況，每五年通盤檢討一次，並作必要之變更；但有為興辦重要或緊急保育措施、為防治重大或緊急災害、政府為促進公共福祉或興辦國防所辦理之必要性公共建設等情事之一者，得隨時檢討之。第2項：計畫之變更應依第9條、第16條及第17條程序辦理。",
 "How often must the plans be comprehensively reviewed after announcement, and when may review occur at any time?",
 ["Every five years in light of coastal conditions, with necessary changes; but review may occur at any time for important or urgent conservation measures, for preventing major or urgent disasters, or for necessary public works for public welfare or national defense","Every ten years in light of coastal conditions, with necessary changes; but review may occur at any time for important or urgent conservation measures, for preventing major or urgent disasters, or for necessary public works for public welfare or national defense","Every three years in light of coastal conditions, with necessary changes; but review at other times is allowed only after a major coastal disaster makes the plan clearly unsuitable and the Executive Yuan approves the central authority's request","Every five years in light of coastal conditions, with necessary changes; once announced the plan may not be altered outside review periods, so even major disasters or defense needs must await the next comprehensive review"],
 "Article 18, paragraphs 1 and 2."),

(CM,"第19條",2,"海管法-相關計畫變更",
 "整體海岸管理計畫、海岸保護計畫、海岸防護計畫公告實施後，其他相關計畫應如何配合？",
 ["依計畫內容應修正或變更之開發計畫、事業建設計畫、都市計畫、國家公園計畫或區域計畫，相關主管機關應按各計畫所定期限辦理變更作業","依計畫內容應修正之開發計畫、都市計畫或區域計畫，相關主管機關得自行決定是否辦理變更，海岸相關計畫不生拘束其他計畫之效力","開發計畫、事業建設計畫、都市計畫、國家公園計畫或區域計畫仍優先適用，海岸相關計畫應配合各該計畫內容修正後重新公告實施","相關主管機關應於海岸計畫公告後三個月內全面停止執行原有之開發計畫、都市計畫及區域計畫，俟重新擬訂完成後始得恢復實施"],"a",
 "第19條：整體海岸管理計畫、海岸保護計畫、海岸防護計畫公告實施後，依計畫內容應修正或變更之開發計畫、事業建設計畫、都市計畫、國家公園計畫或區域計畫，相關主管機關應按各計畫所定期限辦理變更作業。第27條並要求區域計畫、都市計畫主要計畫或國家公園計畫在海岸地區範圍者，於審議通過前應先徵詢主管機關之意見。",
 "How must other plans respond once the coastal plans are announced and in force?",
 ["Development plans, undertaking plans, urban plans, national park plans or regional plans that need amendment under those plans must be changed by the relevant authorities within the periods each plan sets","Development plans, urban plans or regional plans needing amendment may be changed at the relevant authority's discretion, since coastal plans do not bind other plans in any way","Development plans, undertaking plans, urban plans, national park plans and regional plans still prevail, so the coastal plans must instead be amended to match their content and then re-announced in full","Relevant authorities must suspend all existing development, urban and regional plans within three months of announcement and may resume only after redrafting is complete"],
 "Article 19; Article 27."),

(CM,"第20條",1,"海管法-航道調整",
 "船舶航行有影響海岸保護或肇致海洋污染之虞者，得如何處理？",
 ["得由中央主管機關會商航政主管機關調整航道，並公告之","得由航政主管機關逕行禁止該船舶進入我國領海並公告之","得由中央主管機關命該船舶所有人負擔海岸復育之全部費用","得由地方主管機關會商漁業主管機關劃定禁航區並公告之"],"a",
 "第20條：船舶航行有影響海岸保護或肇致海洋污染之虞者，得由中央主管機關會商航政主管機關調整航道，並公告之。本法之中央主管機關依第3條為內政部；海洋污染之防治另依海洋污染防治法之規定辦理。",
 "What may be done where ship navigation may affect coastal protection or cause marine pollution?",
 ["The central competent authority may adjust the shipping route in consultation with the maritime authority and announce it","The maritime authority may directly bar that ship from entering ROC territorial waters and announce the prohibition","The central competent authority may order the shipowner to bear the entire cost of coastal restoration work","The local competent authority may delimit a no-sailing area in consultation with the fisheries authority and announce it"],
 "Article 20; Article 3."),

(CM,"第21條",3,"海管法-計畫實施行為",
 "為擬訂及實施海岸相關計畫，計畫擬訂或實施機關得為哪些行為？",
 ["派員進入公私有土地實地調查勘測；與土地所有權人、使用人或管理人協議將無特殊用途之公私有土地作為臨時作業或材料放置場所；拆遷有礙計畫實施之土地改良物；協調漁業主管機關變更廢止漁業權之核准或限制漁業行為；協調礦業或土石採取主管機關劃定禁採區","派員進入公私有土地實地調查勘測；未經協議即得無償使用任何公私有土地作為臨時作業或材料放置場所；逕行拆除全部土地改良物而無須補償；直接廢止範圍內之漁業權並停止漁業行為；逕行撤銷已設定礦區或土石區之礦業權並沒入其全部設備","委託民間廠商進入公私有土地實地調查勘測；標購無特殊用途之公私有土地作為永久作業場所；價購有礙計畫實施之土地改良物；請求漁業主管機關全面收回轄區內漁業權；請求礦業主管機關全面停止核發新礦業權執照","報請上級機關派員進入公私有土地實地調查勘測；徵收無特殊用途之公私有土地作為臨時作業場所；命所有人自行拆除有礙計畫實施之土地改良物；命漁業權人自行放棄漁業權之行使；命礦業權人自行申請縮減其礦區範圍"],"a",
 "第21條第1項：為擬訂及實施整體海岸管理計畫、海岸保護計畫或海岸防護計畫，計畫擬訂或實施機關得派員進入公私有土地實地調查、勘測；與土地所有權人、使用人或管理人協議，將無特殊用途之公私有土地作為臨時作業或材料放置場所；拆遷有礙計畫實施之土地改良物；為強化漁業資源保育或海岸保護，協調漁業主管機關依漁業法規定變更、廢止漁業權之核准、停止漁業權之行使或限制漁業行為；協調礦業或土石採取主管機關於已設定礦區或已核准之土石區依規定劃定禁採區。第3項並定明因該等行為致受損失者，應給予適當之補償。",
 "What acts may the drafting or implementing agency perform to prepare and carry out coastal plans?",
 ["Send personnel onto public or private land to survey; agree with owners, users or managers to use land without special use as a temporary work or material site; demolish improvements obstructing the plan; coordinate the fisheries authority to alter, revoke, suspend or restrict fishing rights; and coordinate mining authorities to delimit no-extraction areas","Send personnel onto land to survey; use any public or private land free of charge as a temporary work or material site without any agreement; demolish all improvements without compensation; abolish fishing rights outright; and revoke mining rights in established mining areas and confiscate the equipment","Commission private contractors to enter and survey public and private land; buy land without special use at tender as a permanent work or storage site; purchase all improvements obstructing the plan; ask the fisheries authority to withdraw every fishing right in the area; and ask mining authorities to stop issuing any new mining or extraction licenses","Ask the superior agency to send personnel to survey the land; expropriate land without special use as a temporary work site; order owners to demolish obstructing improvements themselves; order fishing right holders to renounce their rights; and order mining right holders to apply to shrink their mining areas"],
 "Article 21, paragraphs 1 and 3."),

(CM,"第21條",2,"海管法-進入土地程序",
 "調查或勘測人員進入公私有土地時，應踐行哪些程序？補償金額如何決定？",
 ["應出示執行職務有關之證明文件或顯示足資辨別之標誌，土地所有人、占有人、管理人或使用人不得規避、拒絕或妨礙；進入設有圍障之土地前，應於七日前通知其所有人、占有人、管理人或使用人；補償金額或方式由雙方協議，協議不成者由計畫擬訂或實施機關報請上級主管機關核定","應出示執行職務有關之證明文件或顯示足資辨別之標誌，土地所有人得於認有妨礙其權益時拒絕人員進入；進入設有圍障之土地前，應於三十日前通知其所有人或管理人；補償之金額或方式一律由計畫擬訂或實施機關逕行核定並通知，土地所有人不得聲明異議或提起救濟","得逕行進入而免出示任何證明文件或標誌，土地所有人、占有人、管理人或使用人不得規避、拒絕或妨礙；進入設有圍障之土地前，得於進入之當日口頭通知；補償金額或方式由中央主管機關統一訂定標準表，不因個案情形而有差異","應先取得法院核發之許可裁定始得進入，土地所有人得於裁定送達後聲明異議；進入設有圍障之土地前，應於十四日前以雙掛號通知其所有人；補償金額或方式應由雙方逕行提付仲裁，不得報請上級主管機關核定"],"a",
 "第21條第2項：調查或勘測人員進入公、私有土地調查或勘測時，應出示執行職務有關之證明文件或顯示足資辨別之標誌；土地所有人、占有人、管理人或使用人不得規避、拒絕或妨礙；於進入設有圍障之土地調查或勘測前，應於七日前通知其所有人、占有人、管理人或使用人。第4項：補償金額或方式由雙方協議之；協議不成者，由計畫擬訂或實施機關報請上級主管機關核定。第35條對規避、妨礙或拒絕調查、勘測者，處新臺幣一萬元以上五萬元以下罰鍰。",
 "What procedure applies when survey personnel enter land, and how is compensation determined?",
 ["They must show credentials or a clear identifying mark, and owners, possessors, managers or users may not evade, refuse or obstruct; enclosed land requires seven days' prior notice to them; compensation is agreed by the parties, failing which the agency reports it to the superior authority for approval","They must show credentials or a clear identifying mark, but the owner may refuse entry where rights are thought to be prejudiced; enclosed land requires thirty days' prior notice; compensation is fixed by the agency alone and the owner may not object to it","They may enter without showing any credentials or mark, and owners, possessors, managers or users may not evade, refuse or obstruct; enclosed land may be entered on oral notice the same day; compensation follows a uniform national schedule of amounts regardless of the circumstances of the individual case","They must first obtain a court order before entering, and the owner may object once it is served; enclosed land requires fourteen days' prior notice by registered mail; compensation must be submitted to arbitration and may not be approved by a superior authority"],
 "Article 21, paragraphs 2 and 4; Article 35."),

(CM,"第22條",2,"海管法-受益費",
 "因海岸防護計畫有關工程而受直接利益者，計畫擬訂及實施機關得為何種徵收？其徵收依據為何？",
 ["得於其受益限度內徵收防護工程受益費；其徵收依工程受益費徵收條例規定辦理","得於其受益限度內徵收海岸管理特別捐；其徵收依地方稅法通則規定辦理","得按其土地公告現值比例徵收海岸開發影響費；其徵收依土地稅法規定辦理","得依其營業額比例徵收海岸資源使用費；其徵收依規費法之規定辦理並公告"],"a",
 "第22條第1項：因海岸防護計畫有關工程而受直接利益者，計畫擬訂及實施機關得於其受益限度內，徵收防護工程受益費。第2項：防護工程受益費之徵收，依工程受益費徵收條例規定辦理。第29條並定有海岸管理基金之來源，包括政府機關循預算程序之撥款、基金孳息收入、受贈收入及其他收入。",
 "What charge may be levied on those directly benefiting from coastal defense works, and under what law?",
 ["A defense works benefit charge may be levied within the limit of the benefit received, collected under the Statute for Collection of Engineering Benefit Charges","A special coastal management levy may be imposed within the limit of the benefit received, collected under the general provisions of the Local Tax Act","A coastal development impact fee may be levied in proportion to assessed land value, collected under the provisions of the Land Tax Act","A coastal resource use fee may be levied in proportion to turnover, collected and announced under the provisions of the Charges and Fees Act"],
 "Article 22; Article 29."),

(CM,"第23條",2,"海管法-設計手冊",
 "海岸防護設施之規劃設計手冊，應由誰訂定？訂定時應考慮哪些因素？",
 ["由中央水利主管機關會商相關目的事業主管機關訂定；應考慮海象、氣象、地形、地質、地盤變動、侵蝕狀態、其他海岸狀況與因波力、設施重量、水壓、土壓、風壓、地震及漂流物等因素與衝擊","由中央主管機關會商內政部營建署訂定；應考慮土地權屬、地價水準、開發強度、容積率、建蔽率、公共設施用地比例、交通運輸系統、地方財政負擔能力及居民意願等因素與影響","由各直轄市、縣（市）主管機關分別訂定；應考慮轄區人口成長、產業結構、觀光遊憩需求、漁業生產規模、聚落分布密度及地方預算編列情形等因素與衝擊","由中央主管機關委託民間工程顧問公司訂定；應考慮工程造價、施工工期、廠商施工能量、材料供應穩定度、機具調度及保固期間之維護成本等因素與影響"],"a",
 "第23條：中央水利主管機關應會商相關目的事業主管機關考慮海象、氣象、地形、地質、地盤變動、侵蝕狀態、其他海岸狀況與因波力、設施重量、水壓、土壓、風壓、地震及漂流物等因素與衝擊，訂定海岸防護設施之規劃設計手冊。第2條第3款定明海岸防護設施包括堤防、突堤、離岸堤、護岸、胸牆、滯（蓄）洪池、地下水補注設施、抽水設施及防潮閘門等。",
 "Who issues the planning and design manual for coastal defense facilities, and what must be considered?",
 ["The central water authority, in consultation with the relevant industry authorities; it must consider sea and weather conditions, terrain, geology, ground movement, erosion, other coastal conditions, and wave force, facility weight, water, earth and wind pressure, earthquakes and drifting objects","The central competent authority, in consultation with the construction agency; it must consider land ownership, land price levels, development intensity, floor area and building coverage ratios, public facility land ratios, transport systems and the fiscal capacity of the local government concerned","Each municipal and county competent authority separately; it must consider local population growth, industrial structure, tourism demand, fishery production scale, settlement density and the state of local budget appropriations","The central competent authority, through commissioned private engineering consultants; it must consider construction cost, schedule, contractor capacity, material supply stability, equipment scheduling and warranty-period maintenance costs"],
 "Article 23; Article 2, subparagraph 3."),

(CM,"第24條",1,"海管法-兼有效用設施",
 "海岸防護設施如兼有道路、水門、起卸貨場等其他設施之效用時，應由誰實施工程並維護管理？",
 ["由該其他設施之主管機關實施該海岸防護設施之工程，並維護管理","由中央水利主管機關統一實施該工程，其他設施主管機關僅負協助","由計畫擬訂機關實施該工程後，移交地方主管機關維護及管理","由中央主管機關委託民間機構實施該工程並委託經營維護管理"],"a",
 "第24條：海岸防護設施如兼有道路、水門、起卸貨場等其他設施之效用時，由該其他設施主管機關實施該海岸防護設施之工程，並維護管理。第14條第3項亦採類似之權責分工，就因興辦事業計畫實施所造成之海岸侵蝕，由各該興辦事業計畫之目的事業主管機關辦理防護措施。",
 "Who builds and maintains a coastal defense facility that also serves as a road, water gate or loading yard?",
 ["The authority in charge of that other facility carries out the works and maintains and manages it","The central water authority carries out all such works, with the other facility's authority merely assisting","The plan drafting agency builds it and then transfers it to the local competent authority for maintenance","The central competent authority commissions a private entity to build it and to operate and maintain it"],
 "Article 24; Article 14, paragraph 3."),

(CM,"第25條",3,"海管法-利用許可",
 "在一級海岸保護區以外之海岸地區特定區位內從事一定規模以上開發利用者，應踐行何種程序？",
 ["申請人應檢具海岸利用管理說明書，申請中央主管機關許可；未經中央主管機關許可前，各目的事業主管機關不得為開發、工程行為之許可","申請人應檢具環境影響說明書，申請目的事業主管機關許可；經目的事業主管機關許可後，再報請中央主管機關備查即可逕行開發施工","申請人應檢具海岸利用管理說明書，向地方主管機關報備；地方主管機關備查後，各目的事業主管機關即得逕為開發、工程行為之許可","申請人應檢具開發計畫書及財務計畫，申請行政院核定；於行政院核定前，各目的事業主管機關得先行核發開發及工程行為之許可"],"a",
 "第25條第1項：在一級海岸保護區以外之海岸地區特定區位內，從事一定規模以上之開發利用、工程建設、建築或使用性質特殊者，申請人應檢具海岸利用管理說明書，申請中央主管機關許可。第2項：前項申請未經中央主管機關許可前，各目的事業主管機關不得為開發、工程行為之許可。第3項並授權中央主管機關訂定特定區位、一定規模或性質特殊之適用範圍與說明書格式等辦法。第36條對未經許可或未依許可內容逕行施工者，處新臺幣六萬元以上三十萬元以下罰鍰。",
 "What procedure applies to development above a set scale in specific locations outside a first-class protection zone?",
 ["The applicant must submit a coastal use management statement and obtain the central authority's permit; until that permit is granted, no industry authority may permit the development or engineering work","The applicant must submit an environmental impact statement to the industry authority for permission; once permitted, filing with the central authority for record is enough to begin construction","The applicant must submit a coastal use management statement to the local authority for record; once filed, the industry authorities may go ahead and permit the development or engineering work","The applicant must submit a development plan and financial plan for Executive Yuan approval; before that approval, industry authorities may still issue development and engineering permits"],
 "Article 25; Article 36."),

(CM,"第26條",3,"海管法-許可條件",
 "中央主管機關審查海岸利用許可案件，應符合哪些條件始得許可？",
 ["符合整體海岸管理計畫利用原則；符合海岸保護計畫、海岸防護計畫管制事項；保障公共通行或具替代措施；對海岸生態環境衝擊採取避免或減輕之有效措施；使用自然海岸或填海造地時以最小需用為原則並採取彌補或復育之有效措施","符合區域計畫或都市計畫之土地使用分區；符合建築技術規則所定之建蔽率與容積率；取得全體毗鄰土地所有權人書面同意；對海岸景觀衝擊提出視覺模擬分析；使用自然海岸或填海造地時應繳交等額之開發回饋金予地方政府","符合國土計畫所定之成長管理策略；符合環境影響評估審查結論之附款；取得當地鄉鎮市區公所之同意函；對海岸交通衝擊提出改善方案；使用自然海岸或填海造地時應由申請人另行取得漁業權人與養殖業者之全體同意","符合中央目的事業主管機關之產業發展政策；符合投資金額與就業人數之門檻標準；取得金融機構出具之融資承諾書；對地方財政挹注提出具體承諾；使用自然海岸或填海造地時應優先僱用當地居民並提供技術訓練"],"a",
 "第26條第1項：依第25條第1項申請許可案件，經中央主管機關審查符合下列條件者始得許可：一、符合整體海岸管理計畫利用原則。二、符合海岸保護計畫、海岸防護計畫管制事項。三、保障公共通行或具替代措施。四、對海岸生態環境衝擊採取避免或減輕之有效措施。五、因開發需使用自然海岸或填海造地時，應以最小需用為原則，並於開發區內或鄰近海岸之適當區位，採取彌補或復育所造成生態環境損失之有效措施。第2項並授權中央主管機關定其許可條件之規則。",
 "What conditions must be met before the central authority may grant a coastal use permit?",
 ["Consistency with the integrated plan's use principles; consistency with protection and defense plan controls; safeguarding public passage or providing alternatives; effective measures to avoid or mitigate ecological impact; and, where natural coast or reclamation is used, minimum need plus effective offset or restoration measures","Consistency with regional or urban plan land use zoning; compliance with building coverage and floor area ratios; written consent of all adjoining landowners; a visual simulation of landscape impact; and, where natural coast or reclamation is used, payment of an equivalent development feedback levy to the local government","Consistency with the national spatial plan's growth management strategy; compliance with environmental impact assessment conditions; a letter of consent from the local township office; a plan to ease traffic impact; and, where natural coast or reclamation is used, consent of all fishing right holders and aquaculture operators","Consistency with the central industry authority's development policy; meeting investment amount and employment thresholds; a financing commitment letter from a bank; a concrete pledge of local fiscal contribution; and, where natural coast or reclamation is used, priority hiring of local residents with training"],
 "Article 26."),

(CM,"第27條",2,"海管法-計畫徵詢",
 "區域計畫、都市計畫主要計畫或國家公園計畫在海岸地區範圍者，其審議應踐行何種程序？",
 ["審議機關於計畫審議通過前，應先徵詢主管機關之意見","審議機關於計畫公告實施後，應將計畫函送主管機關備查","審議機關應將計畫送請主管機關審議核定後始得公告實施","審議機關得逕行審議通過，僅須於公告時副知主管機關"],"a",
 "第27條：區域計畫、都市計畫主要計畫或國家公園計畫在海岸地區範圍者，區域計畫、都市計畫主要計畫或國家公園計畫審議機關於計畫審議通過前，應先徵詢主管機關之意見。第19條並要求該等計畫依海岸相關計畫內容應修正或變更者，相關主管機關應按各計畫所定期限辦理變更作業。",
 "What procedure applies when a regional, urban master or national park plan falls within the coastal zone?",
 ["The reviewing body must first seek the competent authority's opinion before approving the plan","The reviewing body must send the plan to the competent authority for record after announcing it","The reviewing body must send the plan to the competent authority for review and approval first","The reviewing body may approve it directly and merely copy the competent authority on announcement"],
 "Article 27; Article 19."),

(CM,"第28條",1,"海管法-獎勵表揚",
 "中央主管機關對於具有公共利益之哪些海岸事項得予適當獎勵及表揚？",
 ["海岸保護、復育、防護、教育、宣導、研發、創作、捐贈、認養與管理事項","海岸開發、填海造地、港埠興建、產業投資、觀光招商與土地開發事項","海岸巡防、查緝走私、取締違規、蒐證移送、通報聯繫與勤務支援事項","海岸漁業、養殖生產、魚苗放流、漁港建設、漁業推廣與行銷通路事項"],"a",
 "第28條：中央主管機關對於具有公共利益之海岸保護、復育、防護、教育、宣導、研發、創作、捐贈、認養與管理事項，得予適當獎勵及表揚。第30條並定明海岸管理基金之用途包括海岸保育及復育補助、海岸保育及復育獎勵、海岸環境教育解說創作及推廣等。",
 "For which coastal matters of public interest may the central authority give appropriate awards and commendations?",
 ["Coastal protection, restoration, defense, education, promotion, research, creative work, donation, adoption and management","Coastal development, land reclamation, port construction, industrial investment, tourism promotion and land development","Coastal patrol, smuggling interdiction, enforcement against violations, evidence-gathering and referral, and duty support","Coastal fisheries, aquaculture production, fry release, fishing port construction, fishery extension and marketing channels"],
 "Article 28; Article 30."),

(CM,"第29條",1,"海管法-基金來源",
 "主管機關為擴大參與及執行海岸保育相關事項所成立之海岸管理基金，其來源為何？",
 ["政府機關循預算程序之撥款、基金孳息收入、受贈收入及其他收入","依本法所處罰鍰之全部收入、基金孳息收入、受贈收入及其他收入","海岸利用許可規費收入、防護工程受益費收入、受贈收入及其他收入","開發業者繳交之回饋金收入、土地租金收入、受贈收入及其他收入"],"a",
 "第29條：主管機關為擴大參與及執行海岸保育相關事項，得成立海岸管理基金，其來源如下：一、政府機關循預算程序之撥款。二、基金孳息收入。三、受贈收入。四、其他收入。第30條並明定基金用途以海岸研究調查規劃監測、環境清理維護、保育復育補助與獎勵、環境教育推廣、國際交流合作等為限。",
 "What are the sources of the coastal management fund?",
 ["Appropriations made by government agencies through the budget process, interest on the fund, donations received and other income","All revenue from fines imposed under this Act, interest earned on the fund, donations received and other miscellaneous income","Coastal use permit fee revenue, defense works benefit charge revenue, donations received and other miscellaneous income","Feedback levies paid by developers, land rental income, donations received and other miscellaneous sources of income"],
 "Article 29; Article 30."),

(CM,"第30條",2,"海管法-基金用途",
 "海岸管理基金之用途限定於下列哪些項目？",
 ["海岸之研究、調查、勘定、規劃、監測相關費用；海岸環境清理與維護；海岸保育及復育補助；海岸保育及復育獎勵；海岸環境教育、解說、創作及推廣；海岸保育國際交流合作","海岸土地之徵收與地價補償費用；海岸開發工程之興建與監造；海岸產業投資補助；海岸招商引資獎勵；海岸觀光行銷、廣告、活動及推廣；海岸產業國際貿易拓銷合作","海岸巡防勤務之裝備與人力費用；海岸監控設施之建置與維護；海岸違規查報補助；海岸檢舉人獎金；海岸治安宣導、講習、演練及推廣；海岸執法國際情報交流合作","海岸主管機關之人事與辦公費用；海岸行政大樓之興建與修繕；海岸業務委外補助；海岸績效考核獎金；海岸公務人員教育、訓練、進修及考察；海岸行政國際參訪交流合作"],"a",
 "第30條：海岸管理基金用途限定如下：一、海岸之研究、調查、勘定、規劃、監測相關費用。二、海岸環境清理與維護。三、海岸保育及復育補助。四、海岸保育及復育獎勵。五、海岸環境教育、解說、創作及推廣。六、海岸保育國際交流合作。七、其他經主管機關核准有關海岸保育、防護及管理之費用。第28條並就具公共利益之海岸保護、復育、教育、認養與管理事項定有獎勵及表揚規定。",
 "To which items is the coastal management fund limited?",
 ["Costs of coastal research, survey, demarcation, planning and monitoring; coastal environmental cleanup and maintenance; subsidies for coastal conservation and restoration; awards for conservation and restoration; coastal environmental education, interpretation, creative work and outreach; and international conservation exchanges","Coastal land expropriation costs and land price compensation; construction and supervision of coastal development works; subsidies for coastal industrial investment; awards for attracting investment; coastal tourism marketing, advertising, events and outreach; and international trade promotion and marketing cooperation","Equipment and manpower costs of coast guard duties; installation and upkeep of coastal surveillance facilities; subsidies for reporting violations; rewards for informants; coastal security publicity, briefings, drills and outreach; and international law enforcement intelligence exchanges","Personnel and office costs of the coastal authority; construction and repair of its administrative buildings; subsidies for outsourced coastal work; performance bonuses; education, training, further study and inspection visits for civil servants; and international administrative exchange visits"],
 "Article 30; Article 28."),

(CM,"第31條",3,"海管法-公共通行",
 "為保障公共通行及公共水域之使用，近岸海域及公有自然沙灘有何限制？其例外為何？",
 ["不得為獨占性使用，並禁止設置人為設施；但符合整體海岸管理計畫並依其他法律規定允許使用設置者，或為國土保安、國家安全、公共運輸、環境保護、學術研究及公共福祉之必要而專案向主管機關申請許可者，不在此限","不得為獨占性使用，並禁止設置人為設施；但經當地鄉鎮市區公所同意並繳納使用費者，或為漁業養殖、觀光遊憩、餐飲營業及水上活動經營之必要而向地方主管機關報備者，不在此限","得為獨占性使用但不得設置永久性人為設施；但符合整體海岸管理計畫並經目的事業主管機關書面同意者，或為國土保安、國家安全、環境保護及公共運輸之必要而向中央主管機關報請備查者，不在此限","不得為獨占性使用，並禁止一切人員進入活動；但為國土保安、國家安全、公共運輸、環境保護、學術研究之必要而經行政院專案核准者，或原住民族基於傳統文化需要者，不在此限"],"a",
 "第31條第1項：為保障公共通行及公共水域之使用，近岸海域及公有自然沙灘不得為獨占性使用，並禁止設置人為設施；但符合整體海岸管理計畫，並依其他法律規定允許使用、設置者，或為國土保安、國家安全、公共運輸、環境保護、學術研究及公共福祉之必要，專案向主管機關申請許可者，不在此限。第2項並授權中央主管機關訂定專案申請許可之程序、應具備文件、許可條件及廢止等辦法。第37條對違反者定有罰則。",
 "What restrictions protect public passage in nearshore waters and public natural beaches, and what exceptions apply?",
 ["Exclusive use is prohibited and artificial facilities may not be installed; except where use or installation is allowed under other laws consistently with the integrated plan, or where a special permit is sought for territorial security, national security, public transport, environmental protection, academic research or public welfare","Exclusive use is prohibited and artificial facilities may not be installed; except with the consent of the local township office and payment of a use fee, or where aquaculture, tourism, catering or water activity operations are filed with the local authority","Exclusive use is allowed but permanent artificial facilities are not permitted; except where the relevant industry authority consents in writing consistently with the integrated coastal management plan, or where territorial security, national security, environmental protection or public transport needs are filed with the central competent authority","Exclusive use is prohibited and all entry by persons is banned; except where the Executive Yuan specially approves territorial security, national security, public transport, environmental protection or academic research needs, or for indigenous traditional culture"],
 "Article 31; Article 37."),

# ---------- 第四章 罰則 ----------
(CM,"第32條",3,"海管法-一級保護區罰則",
 "在一級海岸保護區內違反規定改變資源條件使用或違反保護計畫禁止使用者，其法律責任為何？",
 ["處新臺幣六萬元以上三十萬元以下罰鍰；因該行為毀壞保護標的者，處六月以上五年以下有期徒刑，得併科新臺幣四十萬元以下罰金；因該行為致釀成災害者，處三年以上十年以下有期徒刑，得併科新臺幣六十萬元以下罰金","處新臺幣三萬元以上十五萬元以下罰鍰；因該行為毀壞保護標的者，處五年以下有期徒刑，得併科新臺幣三十萬元以下罰金；因該行為致釀成災害者，處一年以上七年以下有期徒刑，得併科新臺幣五十萬元以下罰金","處新臺幣二萬元以上十萬元以下罰鍰；因該行為毀壞保護標的者，處三年以下有期徒刑、拘役或科或併科新臺幣二十萬元以下罰金；因該行為致釀成災害者，處六月以上五年以下有期徒刑，得併科新臺幣四十萬元以下罰金","處新臺幣一萬元以上五萬元以下罰鍰；因該行為毀壞保護標的者，處二年以下有期徒刑，得併科新臺幣十萬元以下罰金；因該行為致釀成災害者，處六月以上三年以下有期徒刑，得併科新臺幣二十萬元以下罰金"],"a",
 "第32條：在一級海岸保護區內，違反第12條第2項改變其資源條件使用或違反第13條第1項第3款海岸保護計畫所定禁止之使用者，處新臺幣六萬元以上三十萬元以下罰鍰；因前項行為毀壞保護標的者，處六月以上五年以下有期徒刑，得併科新臺幣四十萬元以下罰金；因第1項行為致釀成災害者，處三年以上十年以下有期徒刑，得併科新臺幣六十萬元以下罰金。第38條並定明除罰鍰外應即令其停止使用或施工。",
 "What liability attaches to changing resource conditions or breaching prohibited uses in a first-class protection zone?",
 ["A fine of NT$60,000 to NT$300,000; where the act destroys the protection target, six months to five years' imprisonment with a fine up to NT$400,000; where it causes a disaster, three to ten years' imprisonment with a fine up to NT$600,000","A fine of NT$30,000 to NT$150,000; where the act destroys the protection target, up to five years' imprisonment with a fine up to NT$300,000; where it causes a disaster, one to seven years' imprisonment with a fine up to NT$500,000","A fine of NT$20,000 to NT$100,000; where the act destroys the protection target, up to three years' imprisonment or detention with a fine up to NT$200,000; where it causes a disaster, six months to five years with a fine up to NT$400,000","A fine of NT$10,000 to NT$50,000; where the act destroys the protection target, up to two years' imprisonment with a fine up to NT$100,000; where it causes a disaster, six months to three years with a fine up to NT$200,000"],
 "Article 32; Article 38."),

(CM,"第38條",2,"海管法-併同處分",
 "主管機關對於一級保護區、防護區或二級保護區之違規使用行為，除處以罰鍰外尚應為何種處分？",
 ["應即令其停止使用或施工；並視情形令其限期回復原狀、拆除設施或增建安全設施，屆期未遵從者，得按次處罰","應即移送司法機關偵辦；並由檢察官逕行命其限期回復原狀或拆除設施，屆期未遵從者，由法院裁定強制執行","得視情形令其限期改善；屆期未遵從者，僅得加倍處以罰鍰，不得命其停止使用、回復原狀或拆除相關設施","應即撤銷其一切開發許可；並由主管機關代為回復原狀及拆除設施，所生費用由海岸管理基金全額支應負擔"],"a",
 "第38條：主管機關對第32條第1項、第33條第1項或第34條第1項規定行為，除處以罰鍰外，應即令其停止使用或施工；並視情形令其限期回復原狀、拆除設施或增建安全設施，屆期未遵從者，得按次處罰。第41條並定明因該等行為所生或所得之物及所用之物得沒入之，第42條就犯本法之罪者定明沒收。",
 "Besides a fine, what must the authority order for unlawful uses in protection or defense zones?",
 ["It must at once order the use or construction to stop, and as appropriate order restoration, demolition of facilities or added safety works within a time limit, with repeat penalties if not complied with","It must at once refer the case for prosecution, with the prosecutor ordering restoration or demolition of the facilities within a time limit and the court ordering compulsory execution if not complied with","It may order improvement within a time limit, and if not complied with may only double the fine, having no power to order a stop, restoration or demolition of the facilities","It must at once revoke every development permit, carry out restoration and demolition itself, and have the whole cost met by the coastal management fund"],
 "Article 38; Articles 41 and 42."),

(CM,"第33條",2,"海管法-防護區罰則",
 "在海岸防護區內違反海岸防護計畫所定禁止之使用者，其法律責任為何？",
 ["處新臺幣三萬元以上十五萬元以下罰鍰；因該行為毀壞海岸防護設施者，處五年以下有期徒刑，得併科新臺幣三十萬元以下罰金；因該行為致釀成災害者，處一年以上七年以下有期徒刑，得併科新臺幣五十萬元以下罰金","處新臺幣六萬元以上三十萬元以下罰鍰；因該行為毀壞海岸防護設施者，處六月以上五年以下有期徒刑，得併科新臺幣四十萬元以下罰金；因該行為致釀成災害者，處三年以上十年以下有期徒刑，得併科新臺幣六十萬元以下罰金","處新臺幣二萬元以上十萬元以下罰鍰；因該行為毀壞海岸防護設施者，處三年以下有期徒刑，得併科新臺幣二十萬元以下罰金；因該行為致釀成災害者，處六月以上五年以下有期徒刑，得併科新臺幣四十萬元以下罰金","處新臺幣一萬元以上五萬元以下罰鍰；因該行為毀壞海岸防護設施者，處二年以下有期徒刑，得併科新臺幣十五萬元以下罰金；因該行為致釀成災害者，處六月以上三年以下有期徒刑，得併科新臺幣三十萬元以下罰金"],"a",
 "第33條：在海岸防護區內違反第15條第1項第4款海岸防護計畫所定禁止之使用者，處新臺幣三萬元以上十五萬元以下罰鍰；因前項行為毀壞海岸防護設施者，處五年以下有期徒刑，得併科新臺幣三十萬元以下罰金；因第1項行為致釀成災害者，處一年以上七年以下有期徒刑，得併科新臺幣五十萬元以下罰金。第40條並定明於第一審言詞辯論終結前已作有效回復或補救者得減輕其刑。",
 "What liability attaches to breaching prohibited uses under a coastal defense plan inside a defense zone?",
 ["A fine of NT$30,000 to NT$150,000; where the act destroys a defense facility, up to five years' imprisonment with a fine up to NT$300,000; where it causes a disaster, one to seven years' imprisonment with a fine up to NT$500,000","A fine of NT$60,000 to NT$300,000; where the act destroys a defense facility, six months to five years' imprisonment with a fine up to NT$400,000; where it causes a disaster, three to ten years' imprisonment with a fine up to NT$600,000","A fine of NT$20,000 to NT$100,000; where the act destroys a defense facility, up to three years' imprisonment with a fine up to NT$200,000; where it causes a disaster, six months to five years' imprisonment with a fine up to NT$400,000","A fine of NT$10,000 to NT$50,000; where the act destroys a defense facility, up to two years' imprisonment with a fine up to NT$150,000; where it causes a disaster, six months to three years' imprisonment with a fine up to NT$300,000"],
 "Article 33; Article 40."),

(CM,"第34條",2,"海管法-二級保護區罰則",
 "在二級海岸保護區內違反海岸保護計畫所定禁止之使用者，其法律責任為何？",
 ["處新臺幣二萬元以上十萬元以下罰鍰；因該行為毀壞保護標的者，處三年以下有期徒刑、拘役或科或併科新臺幣二十萬元以下罰金；因該行為致釀成災害者，處六月以上五年以下有期徒刑，得併科新臺幣四十萬元以下罰金","處新臺幣六萬元以上三十萬元以下罰鍰；因該行為毀壞保護標的者，處六月以上五年以下有期徒刑、拘役或科或併科新臺幣四十萬元以下罰金；因該行為致釀成災害者，處三年以上十年以下有期徒刑，得併科新臺幣六十萬元以下罰金","處新臺幣三萬元以上十五萬元以下罰鍰；因該行為毀壞保護標的者，處五年以下有期徒刑、拘役或科或併科新臺幣三十萬元以下罰金；因該行為致釀成災害者，處一年以上七年以下有期徒刑，得併科新臺幣五十萬元以下罰金","處新臺幣一萬元以上五萬元以下罰鍰；因該行為毀壞保護標的者，處二年以下有期徒刑、拘役或科或併科新臺幣十萬元以下罰金；因該行為致釀成災害者，處六月以上三年以下有期徒刑，得併科新臺幣二十萬元以下罰金"],"a",
 "第34條：在二級海岸保護區內違反第13條第1項第3款海岸保護計畫所定禁止之使用者，處新臺幣二萬元以上十萬元以下罰鍰；因前項行為毀壞保護標的者，處三年以下有期徒刑、拘役或科或併科新臺幣二十萬元以下罰金；因第1項行為致釀成災害者，處六月以上五年以下有期徒刑，得併科新臺幣四十萬元以下罰金。第12條第1項後段定明一級保護區以外有保護必要之地區得劃設為二級海岸保護區。",
 "What liability attaches to breaching prohibited uses under a protection plan inside a second-class protection zone?",
 ["A fine of NT$20,000 to NT$100,000; where the act destroys the protection target, up to three years' imprisonment or detention with a fine up to NT$200,000; where it causes a disaster, six months to five years' imprisonment with a fine up to NT$400,000","A fine of NT$60,000 to NT$300,000; where the act destroys the protection target, six months to five years' imprisonment or detention with a fine up to NT$400,000; where it causes a disaster, three to ten years' imprisonment with a fine up to NT$600,000","A fine of NT$30,000 to NT$150,000; where the act destroys the protection target, up to five years' imprisonment or detention with a fine up to NT$300,000; where it causes a disaster, one to seven years' imprisonment with a fine up to NT$500,000","A fine of NT$10,000 to NT$50,000; where the act destroys the protection target, up to two years' imprisonment or detention with a fine up to NT$100,000; where it causes a disaster, six months to three years' imprisonment with a fine up to NT$200,000"],
 "Article 34; Article 12."),

(CM,"第35條",2,"海管法-規避調查",
 "規避、妨礙或拒絕計畫擬訂或實施機關派員進入公私有土地實地調查、勘測者，應如何處罰？",
 ["處新臺幣一萬元以上五萬元以下之罰鍰，並得按次處罰及強制檢查","處新臺幣二萬元以上十萬元以下之罰鍰，並得按次處罰及命其停工","處新臺幣六萬元以上三十萬元以下之罰鍰，並得限期令其回復原狀","處新臺幣三千元以上一萬五千元以下之罰鍰，但不得按次處罰或強制檢查"],"a",
 "第35條：規避、妨礙或拒絕第21條第1項第1款之調查、勘測者，處新臺幣一萬元以上五萬元以下之罰鍰，並得按次處罰及強制檢查。第21條第2項規定調查或勘測人員應出示證明文件或顯示足資辨別之標誌，土地所有人、占有人、管理人或使用人不得規避、拒絕或妨礙，並應於進入設有圍障之土地前七日通知。",
 "How is evading, obstructing or refusing an on-site survey by the planning or implementing agency penalized?",
 ["A fine of NT$10,000 to NT$50,000, with repeat penalties and compulsory inspection","A fine of NT$20,000 to NT$100,000, with repeat penalties and a stop-work order","A fine of NT$60,000 to NT$300,000, with an order to restore within a time limit","A fine of NT$3,000 to NT$15,000, but with no repeat penalty or compulsory inspection"],
 "Article 35; Article 21, paragraphs 1 and 2."),

(CM,"第36條",2,"海管法-未經許可施工",
 "違反第二十五條第一項規定，未經主管機關許可或未依許可內容逕行施工者，應如何處罰？",
 ["處新臺幣六萬元以上三十萬元以下罰鍰，並令其限期改善或回復原狀，屆期未遵從者，得按次處罰","處新臺幣一萬元以上五萬元以下罰鍰，並令其限期改善或回復原狀，屆期未遵從者，得移送司法機關","處新臺幣二萬元以上十萬元以下罰鍰，並得撤銷其開發許可，屆期未回復原狀者，得代為執行並求償","處新臺幣三萬元以上十五萬元以下罰鍰，並令其立即停工，屆期未遵從者，得處以三年以下有期徒刑"],"a",
 "第36條：違反第25條第1項規定，未經主管機關許可或未依許可內容逕行施工者，處新臺幣六萬元以上三十萬元以下罰鍰，並令其限期改善或回復原狀，屆期未遵從者，得按次處罰。第25條第1項規定於一級海岸保護區以外之海岸地區特定區位內從事一定規模以上開發利用者，應檢具海岸利用管理說明書申請中央主管機關許可；第26條並定其許可條件。",
 "How is construction without a permit or contrary to a permit under Article 25(1) penalized?",
 ["A fine of NT$60,000 to NT$300,000, with an order to improve or restore within a time limit and repeat penalties if not complied with","A fine of NT$10,000 to NT$50,000, with an order to improve or restore within a time limit and referral for prosecution if not complied with","A fine of NT$20,000 to NT$100,000, with revocation of the development permit and substitute execution with cost recovery if not restored","A fine of NT$30,000 to NT$150,000, with an immediate stop-work order and up to three years' imprisonment if not complied with"],
 "Article 36; Articles 25 and 26."),

(CM,"第37條",2,"海管法-獨占性使用罰則",
 "在近岸海域及公有自然沙灘為獨占性使用或設置人為設施者，主管機關應如何處理？",
 ["經主管機關制止並令其限期恢復原狀，屆期未遵從者，處新臺幣一萬元以上五萬元以下罰鍰，並得按次處罰","逕行處新臺幣六萬元以上三十萬元以下罰鍰，並令其限期恢復原狀，屆期未遵從者，得移送司法機關偵辦","經主管機關制止後即應自行拆除，未拆除者處新臺幣十萬元以上五十萬元以下罰鍰，並得沒入其設施設備","經主管機關制止並令其限期恢復原狀，屆期未遵從者，處三年以下有期徒刑，得併科新臺幣二十萬元以下罰金"],"a",
 "第37條：違反第31條第1項規定，在近岸海域及公有自然沙灘為獨占性使用或設置人為設施者，經主管機關制止並令其限期恢復原狀，屆期未遵從者，處新臺幣一萬元以上五萬元以下罰鍰，並得按次處罰。第31條第1項旨在保障公共通行及公共水域之使用，並就依其他法律允許使用或專案申請許可者設有但書。",
 "How does the authority deal with exclusive use or artificial facilities on nearshore waters and public natural beaches?",
 ["The authority stops the act and orders restoration within a time limit; if not complied with, a fine of NT$10,000 to NT$50,000 applies with repeat penalties","A fine of NT$60,000 to NT$300,000 is imposed directly with an order to restore within a time limit, and referral for prosecution if not complied with","The person must dismantle it once stopped, and failing that a fine of NT$100,000 to NT$500,000 applies with confiscation of the facilities and equipment","The authority stops the act and orders restoration within a time limit; if not complied with, up to three years' imprisonment with a fine up to NT$200,000 applies"],
 "Article 37; Article 31, paragraph 1."),

(CM,"第38條",2,"海管法-停止使用",
 "主管機關對於保護區或防護區之違規行為，除罰鍰外應命行為人為哪些作為？",
 ["應即令其停止使用或施工，並視情形令其限期回復原狀、拆除設施或增建安全設施","應即令其停止使用或施工，並一律令其於三十日內拆除全部設施且不得回復使用","應即令其繳交等額之環境復育保證金，並由主管機關代為回復原狀及拆除設施","應即令其接受環境教育講習課程，並視情形令其限期提出生態補償替代方案"],"a",
 "第38條：主管機關對第32條第1項、第33條第1項或第34條第1項規定行為，除處以罰鍰外，應即令其停止使用或施工；並視情形令其限期回復原狀、拆除設施或增建安全設施，屆期未遵從者，得按次處罰。第32條至第34條分別就一級海岸保護區、海岸防護區及二級海岸保護區之違規使用定有罰鍰及刑罰。",
 "Besides fines, what must the authority order for violations in protection or defense zones?",
 ["It must at once order the use or construction to stop, and as appropriate order restoration, demolition of facilities or added safety works within a time limit","It must at once order the use or construction to stop, and always order all facilities demolished within thirty days with no resumption of use permitted","It must at once order payment of an equivalent environmental restoration deposit, with the authority itself carrying out restoration and demolition","It must at once order attendance at environmental education classes, and as appropriate order an ecological offset alternative within a time limit"],
 "Article 38; Articles 32-34."),

(CM,"第39條",2,"海管法-兩罰規定",
 "法人之代表人、代理人、受雇人或其他從業人員因執行業務犯本法之罪者，法人或自然人之責任為何？",
 ["除處罰其行為人外，對該法人或自然人亦科以各該條之罰金","僅處罰實際行為人，該法人或自然人不另負擔任何刑事責任","僅對該法人或自然人科以罰金，實際行為人得免除刑事責任","應由該法人或自然人與行為人負連帶賠償責任，但不科罰金"],"a",
 "第39條：法人之代表人、法人或自然人之代理人、受雇人或其他從業人員，因執行業務犯本法之罪者，除處罰其行為人外，對該法人或自然人亦科以各該條之罰金。本法所定之罪包括第32條至第34條因違規使用而毀壞保護標的、毀壞海岸防護設施或致釀成災害之情形。",
 "Where a representative, agent or employee commits an offense under this Act in the course of business, what is the entity's liability?",
 ["Besides punishing the actual offender, the juridical or natural person is also fined under the relevant article","Only the actual offender is punished, and the juridical or natural person bears no further criminal liability","Only the juridical or natural person is fined, and the actual offender is exempted from criminal liability","The juridical or natural person is jointly liable in damages with the offender, but no fine is imposed"],
 "Article 39; Articles 32-34."),

(CM,"第40條",2,"海管法-減輕其刑",
 "犯第三十二條至第三十四條之罪者，於何種情形下得減輕其刑？",
 ["於第一審言詞辯論終結前已作有效回復或補救者，得減輕其刑","於偵查中自白並繳交罰金者，得減輕其刑至二分之一","於第二審判決前與主管機關成立和解者，得免除其刑","於犯罪後六個月內自首並提出復育計畫者，應免除其刑"],"a",
 "第40條：犯第32條至第34條之罪，於第一審言詞辯論終結前已作有效回復或補救者，得減輕其刑。第32條至第34條分別規定在一級海岸保護區、海岸防護區及二級海岸保護區內違規使用而毀壞保護標的、毀壞海岸防護設施或致釀成災害之刑責；第38條並定明主管機關應令其限期回復原狀或拆除設施。",
 "In what circumstance may the sentence for an Article 32-34 offense be reduced?",
 ["Where effective restoration or remedial action has been made before the close of oral argument at first instance","Where the offender confesses during investigation and pays the fine, allowing a reduction of up to one half","Where the offender settles with the competent authority before the second instance judgment, remitting the sentence","Where the offender surrenders within six months of the offense and submits a restoration plan, remitting the sentence"],
 "Article 40; Articles 32-34 and 38."),

(CM,"第41條",2,"海管法-沒入",
 "因第三十二條第一項、第三十三條第一項或第三十四條第一項之行為所生或所得之物及所用之物，應如何處理？",
 ["得沒入之","應沒收之","應發還原所有人","應拍賣並繳庫"],"a",
 "第41條：因第32條第1項、第33條第1項或第34條第1項之行為所生或所得之物及所用之物，得沒入之。此為行政罰之沒入規定；第42條另定明犯本法之罪者，其所生或所得之物及所用之物沒收之，屬刑事沒收規定，二者適用之程序與要件不同。",
 "How are objects produced by, obtained from or used in acts under Articles 32(1), 33(1) or 34(1) treated?",
 ["They may be administratively confiscated","They must be criminally confiscated","They must be returned to their owner","They must be auctioned and paid to the treasury"],
 "Article 41; Article 42."),

(CM,"第42條",2,"海管法-沒收",
 "犯本法之罪者，其所生或所得之物及所用之物應如何處理？",
 ["沒收之","沒入之","發還之","變賣之"],"a",
 "第42條：犯本法之罪，其所生或所得之物及所用之物，沒收之。相較之下，第41條係就第32條第1項、第33條第1項或第34條第1項之行政違規行為，規定其所生、所得及所用之物「得沒入之」，屬行政罰性質，二者規範層次不同。",
 "How are objects produced by, obtained from or used in a criminal offense under this Act treated?",
 ["They are criminally confiscated","They are administratively seized","They are returned to the owner","They are appraised and sold"],
 "Article 42; Article 41."),

# ---------- 第五章 附則 ----------
(CM,"第43條",1,"海管法-執行疑義",
 "整體海岸管理計畫及海岸保護計畫、海岸防護計畫涉及相關機關執行有疑義時，應如何處理？",
 ["得由主管機關協調；協調不成，由主管機關報請上級機關決定之","得由目的事業主管機關逕行決定；相關機關均應受該決定之拘束","應由行政院逕行指定主辦機關；主管機關不得介入協調相關爭議","應由計畫擬訂機關函請立法院解釋；相關機關應依解釋內容辦理"],"a",
 "第43條：整體海岸管理計畫及海岸保護計畫、海岸防護計畫涉及相關機關執行有疑義時，得由主管機關協調；協調不成，由主管機關報請上級機關決定之。第10條第1項亦就保護區、防護區等級及計畫擬訂機關認定有疑義者，定有由中央主管機關協調指定或逕行擬訂之機制。",
 "How are doubts among agencies over implementing the coastal plans resolved?",
 ["The competent authority may coordinate; failing agreement, it reports the matter to the superior agency for decision","The relevant industry authority decides directly, and all other agencies are bound by that decision","The Executive Yuan designates a lead agency directly, and the competent authority may not coordinate","The drafting agency asks the Legislative Yuan for an interpretation, which the relevant agencies must then follow"],
 "Article 43; Article 10."),

(CM,"第44條",2,"海管法-計畫期限",
 "中央主管機關應於何時公告實施整體海岸管理計畫？",
 ["應於本法施行後二年內公告實施","應於本法施行後六個月內公告實施","應於本法施行後五年內公告實施","應於本法施行後一年內公告實施"],"a",
 "第44條：中央主管機關應於本法施行後二年內，公告實施整體海岸管理計畫。第5條另規定中央主管機關應於本法施行後六個月內劃定海岸地區範圍後公告之；第18條並要求計畫公告實施後每五年通盤檢討一次。",
 "By when must the central authority announce and implement the integrated coastal zone management plan?",
 ["Within two years after this Act takes effect","Within six months after this Act takes effect","Within five years after this Act takes effect","Within one year after this Act takes effect"],
 "Article 44; Articles 5 and 18."),

(CM,"第45條",1,"海管法-施行細則",
 "本法施行細則之訂定機關為何？",
 ["由中央主管機關定之","由行政院會商定之","經立法院審議後定之","由地方主管機關定之"],"a",
 "第45條：本法施行細則，由中央主管機關定之。依第3條，本法之中央主管機關為內政部。本法另授權中央主管機關訂定之辦法包括第12條第4項不合保護計畫之認定與補償辦法、第25條第3項海岸利用管理說明書辦法及第31條第2項專案申請許可辦法等。",
 "Which authority prescribes the enforcement rules of this Act?",
 ["The central competent authority","The Executive Yuan after consultation","Subject to Legislative Yuan review","Each local competent authority"],
 "Article 45; Articles 3, 12, 25 and 31."),

(CM,"第46條",1,"海管法-施行日",
 "本法之施行日期如何規定？",
 ["自公布日施行","由行政院定之","自公布後六個月施行","自公布後一年施行"],"a",
 "第46條：本法自公布日施行。第44條另定中央主管機關應於本法施行後二年內公告實施整體海岸管理計畫，第5條則要求於施行後六個月內劃定公告海岸地區範圍，二者均以本法施行日為起算基準。",
 "How is the effective date of this Act provided?",
 ["It takes effect on the date of promulgation","It takes effect on a date set by the Executive Yuan","It takes effect six months after promulgation","It takes effect one year after promulgation"],
 "Article 46; Articles 5 and 44."),
]
